}

/*================================*
* Filter Panel
*=================================*/
.users-filter-panel {
  display: none;
  margin-bottom: 20px;
  padding: 20px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.035);
  animation: usersFilterShow 0.2s ease;
}
.users-filter-panel.is-open {
  display: block;
}
@media (max-width: 767px) {
  .users-filter-panel {
    padding: 16px;
    margin-bottom: 16px;
    border-radius: 10px;
  }
}

@keyframes usersFilterShow {
  from {
    opacity: 0;
    transform: translateY(-5px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.users-filter-group label {
  display: block;
  margin-bottom: 8px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
}

.users-filter-input {
  position: relative;
}
.users-filter-input i {
  position: absolute;
  left: 13px;
  top: 50%;
  transform: translateY(-50%);
  color: #555555;
  font-size: 18px;
  pointer-events: none;
}
.users-filter-input input {
  width: 100%;
  height: 42px;
  padding: 0 13px 0 40px;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  transition: 0.2s ease;
}
.users-filter-input input:focus {
  outline: none;
  border-color: #177245;
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.08);
}
.users-filter-input input::placeholder {
  color: rgba(85, 85, 85, 0.65);
}

.users-filter-group select {
  width: 100%;
  height: 42px;
  padding: 0 12px;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  cursor: pointer;
  transition: 0.2s ease;
}
.users-filter-group select:focus {
  outline: none;
  border-color: #177245;
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.08);
}

.users-filter-submit {
  width: 100%;
  min-height: 42px;
  border: 1px solid #177245;
  border-radius: 7px;
  background: #177245;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s ease;
}
.users-filter-submit i {
  font-size: 17px;
}
.users-filter-submit:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
}

/*================================*
* Table Card
*=================================*/
.users-table-card {
  overflow: hidden;
