    flex-direction: column;
  }
}

.users-table-card__heading h2 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.3;
}
@media (min-width: 768px) and (max-width: 991px) {
  .users-table-card__heading h2 {
    font-size: 18px;
  }
}
@media (max-width: 767px) {
  .users-table-card__heading h2 {
    font-size: 17px;
  }
}
.users-table-card__heading p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
@media (max-width: 767px) {
  .users-table-card__heading p {
    font-size: 14px;
  }
}

.users-table-card__tools {
  flex-shrink: 0;
}
@media (max-width: 767px) {
  .users-table-card__tools {
    width: 100%;
  }
}

.users-count {
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid rgba(23, 114, 69, 0.15);
  border-radius: 6px;
  background: rgba(23, 114, 69, 0.05);
  color: #177245;
  font-size: 14px;
  font-weight: 600;
}

/*================================*
* Table Wrapper
*=================================*/
.users-table-wrapper {
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
  scrollbar-color: #ddd rgba(242, 244, 247, 0.7);
}
.users-table-wrapper::-webkit-scrollbar {
  height: 7px;
}
.users-table-wrapper::-webkit-scrollbar-track {
  background: rgba(242, 244, 247, 0.7);
  border-radius: 10px;
}
.users-table-wrapper::-webkit-scrollbar-thumb {
  background: #ddd;
  border-radius: 10px;
}
.users-table-wrapper::-webkit-scrollbar-thumb:hover {
  background: rgba(221, 221, 221, 0.12);
}

/*================================*
* Users Table
*=================================*/
.users-table {
  width: 100% !important;
  min-width: 900px;
  margin: 0 !important;
  border-collapse: collapse;
  border-spacing: 0;
}
.users-table thead th {
  padding: 14px 16px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.08);
  background: rgba(242, 244, 247, 0.55);
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  text-align: left;
  white-space: nowrap;
}
.users-table thead th:last-child {
  text-align: right;
}
@media (min-width: 1200px) and (max-width: 1399px) {
  .users-table thead th {
    padding: 13px 14px;
  }
}
@media (min-width: 992px) and (max-width: 1199px) {
  .users-table thead th {
    padding: 12px 13px;
  }
}
.users-table tbody tr {
  transition: background-color 0.2s ease;
}
.users-table tbody tr:hover {
  background: rgba(23, 114, 69, 0.025);
}
.users-table tbody tr:last-child td {
  border-bottom: 0;
}
.users-table tbody td {
  padding: 15px 16px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.065);
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
  vertical-align: middle;
  white-space: nowrap;
}
.users-table tbody td:last-child {
  text-align: right;
}
@media (min-width: 1200px) and (max-width: 1399px) {
  .users-table tbody td {
    padding: 14px;
  }
}
@media (min-width: 992px) and (max-width: 1199px) {
  .users-table tbody td {
    padding: 13px;
    font-size: 14px;
  }
}

/*================================*
* User Profile
*=================================*/
.user-profile {
  min-width: 250px;
  display: flex;
  align-items: center;
  gap: 11px;
}

.user-profile__avatar {
  width: 40px;
  height: 40px;
  overflow: hidden;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 40px;
  font-size: 14px;
  font-weight: 700;
}
.user-profile__avatar img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.user-profile__info {
  min-width: 0;
}
.user-profile__info strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
}
.user-profile__info span {
  display: block;
  max-width: 210px;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

/*================================*
* Role
*=================================*/
.user-role {
  min-height: 30px;
  padding: 6px 10px;
  border-radius: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

.user-role--admin {
  background: rgba(23, 114, 69, 0.1);
  color: #177245;
}

.user-role--staff {
  background: rgba(13, 202, 240, 0.1);
  color: rgba(13, 202, 240, 0.15);
}

.user-role--client {
  background: rgba(25, 135, 84, 0.09);
  color: rgba(25, 135, 84, 0.8);
}

.user-role--default {
  background: rgba(16, 26, 35, 0.06);
  color: #555555;
}

/*================================*
* Phone
*=================================*/
.user-phone {
  color: #555555;
  font-size: 14px;
  font-weight: 500;
}

/*================================*
* Status
*=================================*/
.user-status {
  min-height: 30px;
  padding: 6px 10px;
  border-radius: 20px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
}
.user-status > span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.user-status--active {
  background: rgba(25, 135, 84, 0.09);
  color: #198754;
}

.user-status--inactive {
  background: rgba(16, 26, 35, 0.06);
  color: #555555;
}

.user-status--pending {
  background: rgba(255, 193, 7, 0.13);
  color: rgba(255, 193, 7, 0.2);
}

.user-status--suspended {
  background: rgba(220, 53, 69, 0.09);
  color: #dc3545;
}

.user-status--default {
  background: rgba(16, 26, 35, 0.06);
  color: #555555;
}

/*================================*
* Date
*=================================*/
.user-date {
  color: #555555;
  font-size: 14px;
  font-weight: 500;
}

/*================================*
* User Actions
*=================================*/
.user-actions {
  display: inline-flex;
