  position: relative;
  min-height: 58px;
  padding: 11px 0 11px 21px;
  border-left: 1px solid rgba(23, 114, 69, 0.18);
  display: flex;
  align-items: flex-start;
}
.user-details-activity__item:last-child {
  border-left-color: transparent;
}
.user-details-activity__item strong {
  display: block;
  margin-bottom: 4px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.35;
}
.user-details-activity__item span:not(.user-details-activity__dot) {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

.user-details-activity__dot {
  position: absolute;
  top: 15px;
  left: -4px;
  width: 8px;
  height: 8px;
  border: 2px solid #fff;
  border-radius: 50%;
  background: #177245;
  box-shadow: 0 0 0 1px rgba(23, 114, 69, 0.18);
}

/*================================*
* Security Box
*=================================*/
.user-details-security {
  padding: 17px;
  border: 1px solid rgba(25, 135, 84, 0.13);
  border-radius: 9px;
  background: rgba(25, 135, 84, 0.035);
  display: flex;
  align-items: flex-start;
  gap: 11px;
}
.user-details-security span {
  display: block;
  margin-bottom: 4px;
  color: #555555;
  font-size: 14px;
}
.user-details-security strong {
  display: block;
  margin-bottom: 5px;
  color: #198754;
  font-size: 14px;
  font-weight: 600;
}
.user-details-security p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

.user-details-security__icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: rgba(25, 135, 84, 0.1);
  color: #198754;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 36px;
}
.user-details-security__icon i {
  font-size: 16px;
}

/*================================*
* Responsive - MD
*=================================*/
@media (min-width: 768px) and (max-width: 991px) {
  .user-details-page__header {
    align-items: flex-start;
  }
  .user-details-layout {
    grid-template-columns: 1fr;
  }
  .user-details-sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: start;
  }
  .user-details-security {
    height: 100%;
  }
  .user-details-summary {
    grid-template-columns: repeat(2, 1fr);
  }
}
/*================================*
* Responsive - XS
*=================================*/
@media (max-width: 767px) {
  .user-details-page__header {
    flex-direction: column;
    align-items: stretch;
  }
  .user-details-page__actions {
    width: 100%;
  }
  .user-details-back-btn,
  .user-details-edit-btn {
    flex: 1;
  }
  .user-details-summary {
    grid-template-columns: 1fr;
  }
  .user-details-sidebar {
    display: flex;
    flex-direction: column;
  }
  .user-details-profile-info {
    align-items: flex-start;
  }
}
/*==============================================================
* Users - Add User
*==============================================================*/
.add-user-page {
  width: 100%;
}

/*==============================================================
* Page Header
*==============================================================*/
.add-user-page__header {
  margin-bottom: 26px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 25px;
}
@media (min-width: 1200px) and (max-width: 1399px) {
  .add-user-page__header {
    margin-bottom: 24px;
  }
}
@media (min-width: 768px) and (max-width: 991px) {
  .add-user-page__header {
    align-items: flex-start;
    flex-direction: column;
    gap: 17px;
  }
}
@media (max-width: 767px) {
  .add-user-page__header {
    margin-bottom: 20px;
    gap: 15px;
  }
}

.add-user-page__heading .add-user-page__eyebrow {
  display: inline-block;
  margin-bottom: 7px;
  color: #177245;
  font-size: 14px;
