  }
}

/*==============================================================
* Validation Alert
*==============================================================*/
.add-user-validation-alert {
  margin-bottom: 20px;
  padding: 14px 16px;
  border: 1px solid rgba(220, 53, 69, 0.14);
  border-radius: 9px;
  background: rgba(220, 53, 69, 0.035);
  display: flex;
  align-items: flex-start;
  gap: 11px;
}
.add-user-validation-alert__icon {
  width: 32px;
  height: 32px;
  border-radius: 7px;
  background: rgba(220, 53, 69, 0.1);
  color: #dc3545;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 32px;
}
.add-user-validation-alert__icon i {
  font-size: 16px;
}
.add-user-validation-alert strong {
  display: block;
  margin-bottom: 5px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.add-user-validation-alert ul {
  margin: 0;
  padding-left: 17px;
}
.add-user-validation-alert li {
  margin-bottom: 3px;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.add-user-validation-alert li:last-child {
  margin-bottom: 0;
}
@media (max-width: 767px) {
  .add-user-validation-alert {
    padding: 12px;
  }
}

/*==============================================================
* Form Layout
*==============================================================*/
.add-user-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 315px;
  gap: 20px;
  align-items: start;
}
@media (min-width: 1200px) and (max-width: 1399px) {
  .add-user-layout {
    grid-template-columns: minmax(0, 1fr) 300px;
  }
}
@media (min-width: 992px) and (max-width: 1199px) {
  .add-user-layout {
    grid-template-columns: minmax(0, 1fr) 285px;
  }
}
@media (min-width: 768px) and (max-width: 991px) {
  .add-user-layout {
    grid-template-columns: 1fr;
  }
}

.add-user-main,
.add-user-sidebar {
  min-width: 0;
}

.add-user-main {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.add-user-sidebar {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/*==============================================================
* Card
*==============================================================*/
.add-user-card {
  overflow: hidden;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.035);
}
@media (max-width: 767px) {
  .add-user-card {
    border-radius: 9px;
  }
}

.add-user-card__header {
  min-height: 67px;
  padding: 16px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.07);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
.add-user-card__header h2 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.3;
}
.add-user-card__header p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.45;
}
.add-user-card__header > i {
  color: #177245;
  font-size: 18px;
}
@media (max-width: 767px) {
  .add-user-card__header {
    padding: 15px 16px;
  }
  .add-user-card__header h2 {
    font-size: 18px;
  }
}

.add-user-card__body {
  padding: 20px;
}
@media (max-width: 767px) {
  .add-user-card__body {
    padding: 16px;
  }
}

/*==============================================================
* Form Grid
*==============================================================*/
.add-user-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 17px 16px;
}
@media (max-width: 767px) {
  .add-user-form-grid {
    grid-template-columns: 1fr;
    gap: 14px;
  }
}

/*==============================================================
* Form Fields
*==============================================================*/
.add-user-field {
  min-width: 0;
}
.add-user-field--full {
  grid-column: 1/-1;
}

.add-user-field > label {
  display: block;
  margin-bottom: 7px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
}
.add-user-field > label > span {
  margin-left: 2px;
  color: #dc3545;
}

.add-user-field__help {
  display: block;
  margin: 7px 0 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*==============================================================
* Inputs
*==============================================================*/
.add-user-input {
  position: relative;
  width: 100%;
}
.add-user-input > i {
  position: absolute;
  top: 50%;
  left: 12px;
  z-index: 2;
  color: #555555;
  font-size: 16px;
  line-height: 1;
  transform: translateY(-50%);
  pointer-events: none;
}
.add-user-input input,
.add-user-input select,
.add-user-input textarea {
  width: 100%;
  border: 1px solid #ddd;
  border-radius: 7px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
}
.add-user-input input:hover,
.add-user-input select:hover,
.add-user-input textarea:hover {
  border-color: rgba(221, 221, 221, 0.07);
}
.add-user-input input:focus,
.add-user-input select:focus,
.add-user-input textarea:focus {
  border-color: #177245;
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.07);
}
.add-user-input input::placeholder,
.add-user-input select::placeholder,
.add-user-input textarea::placeholder {
  color: rgba(85, 85, 85, 0.15);
}
.add-user-input input,
.add-user-input select {
  height: 42px;
  padding: 0 38px 0 37px;
  line-height: 1;
}
.add-user-input select {
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
}
.add-user-input textarea {
  min-height: 115px;
  padding: 12px 13px 12px 37px;
  line-height: 1.55;
  resize: vertical;
}
.add-user-input .add-user-select-icon {
  position: absolute;
  top: 50%;
  right: 11px;
  left: auto;
  z-index: 2;
  color: #555555;
  font-size: 17px;
  transform: translateY(-50%);
  pointer-events: none;
}

/*==============================================================
* Password Toggle
*==============================================================*/
.add-user-password-toggle {
  position: absolute;
  top: 50%;
  right: 9px;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #555555;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transform: translateY(-50%);
  cursor: pointer;
  transition: color 0.2s ease;
}
.add-user-password-toggle i {
  font-size: 15px;
}
.add-user-password-toggle:hover {
  color: #177245;
}
.add-user-password-toggle:focus-visible {
  outline: 2px solid rgba(23, 114, 69, 0.25);
  outline-offset: 2px;
}

/*==============================================================
* Form Error
*==============================================================*/
.form-error {
  display: block;
  margin-top: 5px;
  color: #dc3545;
  font-size: 14px;
  line-height: 1.4;
}

/*==============================================================
* Upload Box
*==============================================================*/
.add-user-upload {
  position: relative;
  min-height: 88px;
  padding: 13px 14px;
  border: 1px dashed rgba(23, 114, 69, 0.3);
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.025);
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  transition: border-color 0.2s ease, background-color 0.2s ease;
}
.add-user-upload input[type=file] {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}
.add-user-upload:hover {
  border-color: #177245;
  background: rgba(23, 114, 69, 0.05);
}
.add-user-upload__icon {
  width: 42px;
  height: 42px;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.1);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 42px;
}
.add-user-upload__icon i {
  font-size: 20px;
}
.add-user-upload__content {
  min-width: 0;
  flex: 1;
}
.add-user-upload__content strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.add-user-upload__content small {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.add-user-upload__button {
  min-height: 32px;
  padding: 0 11px;
  border: 1px solid #ddd;
  border-radius: 6px;
  background: #fff;
  color: #0D2B5A;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  flex-shrink: 0;
}
@media (max-width: 767px) {
  .add-user-upload {
    align-items: flex-start;
  }
  .add-user-upload__button {
    display: none;
  }
}

/*==============================================================
* Password Info
*==============================================================*/
.add-user-password-info {
  margin-top: 18px;
  padding: 12px 13px;
  border: 1px solid rgba(23, 114, 69, 0.1);
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.035);
  display: flex;
  align-items: flex-start;
  gap: 9px;
}
.add-user-password-info > i {
  color: #177245;
  font-size: 16px;
  flex: 0 0 auto;
}
.add-user-password-info strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.add-user-password-info p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*==============================================================
* Checkbox
*==============================================================*/
.add-user-checkbox {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
}
.add-user-checkbox input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.add-user-checkbox__box {
  width: 19px;
  height: 19px;
  border: 1px solid #ddd;
  border-radius: 5px;
  background: #fff;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 19px;
  transition: border-color 0.2s ease, background-color 0.2s ease;
}
.add-user-checkbox__box i {
  font-size: 13px;
  opacity: 0;
}
input:checked + .add-user-checkbox__box {
  border-color: #177245;
  background: #177245;
}
input:checked + .add-user-checkbox__box i {
  opacity: 1;
}
.add-user-checkbox__content {
  min-width: 0;
}
.add-user-checkbox__content strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.add-user-checkbox__content small {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*==============================================================
* Custom Single Role Dropdown
*==============================================================*/
.add-user-role-dropdown {
  position: relative;
  width: 100%;
  /*----------------------------------------------------------
  Trigger
  ----------------------------------------------------------*/
}
.add-user-role-dropdown__trigger {
  position: relative;
  width: 100%;
  min-height: 42px;
  padding: 0 42px 0 37px;
  border: 1px solid #ddd;
  border-radius: 7px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  display: flex;
  align-items: center;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.4;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
}
.add-user-role-dropdown__trigger:hover {
  border-color: rgba(221, 221, 221, 0.07);
}
.add-user-role-dropdown__trigger:focus, .add-user-role-dropdown__trigger[aria-expanded=true] {
  border-color: #177245;
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.07);
}
.add-user-role-dropdown {
  /*----------------------------------------------------------
  Left Icon
  ----------------------------------------------------------*/
}
.add-user-role-dropdown__icon {
  position: absolute;
  top: 50%;
  left: 12px;
  width: 18px;
  height: 18px;
  color: #555555;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transform: translateY(-50%);
  pointer-events: none;
}
.add-user-role-dropdown__icon i {
  font-size: 16px;
  line-height: 1;
}
.add-user-role-dropdown {
  /*----------------------------------------------------------
  Selected Text
  ----------------------------------------------------------*/
}
.add-user-role-dropdown__selected {
  display: block;
  width: 100%;
  overflow: hidden;
  color: rgba(85, 85, 85, 0.05);
  font-size: 14px;
  font-weight: 400;
  line-height: 1.4;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.add-user-role-dropdown__selected.has-selection {
  color: #0D2B5A;
  font-weight: 500;
}
.add-user-role-dropdown {
  /*----------------------------------------------------------
  Arrow
  ----------------------------------------------------------*/
}
.add-user-role-dropdown__arrow {
  position: absolute;
  top: 50%;
  right: 11px;
  color: #555555;
  font-size: 18px;
  line-height: 1;
  transform: translateY(-50%);
  transition: transform 0.2s ease;
  pointer-events: none;
}
.add-user-role-dropdown {
  /*----------------------------------------------------------
  Dropdown Menu
  ----------------------------------------------------------*/
}
.add-user-role-dropdown__menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  z-index: 999;
  width: 100%;
  max-height: 240px;
  padding: 6px;
  overflow-y: auto;
  border: 1px solid rgba(16, 26, 35, 0.09);
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 10px 30px rgba(16, 26, 35, 0.12);
  visibility: hidden;
  opacity: 0;
  transform: translateY(-6px);
  pointer-events: none;
  transition: opacity 0.18s ease, transform 0.18s ease, visibility 0.18s ease;
}
.add-user-role-dropdown__menu::-webkit-scrollbar {
  width: 5px;
}
.add-user-role-dropdown__menu::-webkit-scrollbar-track {
  background: transparent;
}
.add-user-role-dropdown__menu::-webkit-scrollbar-thumb {
  border-radius: 10px;
  background: rgba(16, 26, 35, 0.15);
}
.add-user-role-dropdown {
  /*----------------------------------------------------------
  Open
  ----------------------------------------------------------*/
}
.add-user-role-dropdown.is-open .add-user-role-dropdown__menu {
  visibility: visible;
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}
.add-user-role-dropdown.is-open .add-user-role-dropdown__arrow {
  transform: translateY(-50%) rotate(180deg);
}

/*==============================================================
* Single Role Option
*==============================================================*/
.add-user-role-option {
  position: relative;
  width: 100%;
  min-height: 42px;
  padding: 0 10px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  gap: 9px;
  cursor: pointer;
  transition: background-color 0.15s ease;
}
.add-user-role-option:hover {
  background: rgba(23, 114, 69, 0.05);
}
.add-user-role-option {
  /*----------------------------------------------------------
  Hidden Radio
  ----------------------------------------------------------*/
}
.add-user-role-option input[type=radio] {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  border: 0;
  opacity: 0;
  clip: rect(0 0 0 0);
  pointer-events: none;
}
.add-user-role-option {
  /*----------------------------------------------------------
  Radio Circle
  ----------------------------------------------------------*/
}
.add-user-role-option__check {
  position: relative;
  width: 18px;
  height: 18px;
  border: 1px solid #ddd;
  border-radius: 50%;
  background: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 18px;
  transition: border-color 0.15s ease, background-color 0.15s ease, box-shadow 0.15s ease;
}
.add-user-role-option__check::after {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fff;
  opacity: 0;
  transform: scale(0.5);
  transition: opacity 0.15s ease, transform 0.15s ease;
}
.add-user-role-option {
  /*----------------------------------------------------------
  Role Name
  ----------------------------------------------------------*/
}
.add-user-role-option__name {
  min-width: 0;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.4;
}
.add-user-role-option {
  /*----------------------------------------------------------
  Selected
  ----------------------------------------------------------*/
}
input[type=radio]:checked + .add-user-role-option__check {
  border-color: #177245;
  background: #177245;
  box-shadow: 0 2px 5px rgba(23, 114, 69, 0.12);
}
input[type=radio]:checked + .add-user-role-option__check::after {
  opacity: 1;
  transform: scale(1);
}
input[type=radio]:checked ~ .add-user-role-option__name {
  color: #177245;
  font-weight: 600;
}
.add-user-role-option {
  /*----------------------------------------------------------
  Focus
  ----------------------------------------------------------*/
}
input[type=radio]:focus-visible + .add-user-role-option__check {
  outline: 2px solid rgba(23, 114, 69, 0.25);
  outline-offset: 2px;
}
.add-user-role-option {
  /*----------------------------------------------------------
  Selected Row
  ----------------------------------------------------------*/
}
.add-user-role-option:has(input[type=radio]:checked) {
  background: rgba(23, 114, 69, 0.035);
}

