  transform: translateY(-50%);
  transition: background-color 0.2s ease, color 0.2s ease;
}
.profile-settings .password-toggle i {
  font-size: 17px;
  line-height: 1;
}
.profile-settings .password-toggle:hover {
  background: rgba(23, 114, 69, 0.07);
