  justify-content: center;
  gap: 7px;
  padding: 9px 15px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.2s ease;
}

.filter-button {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.filter-button:hover {
  border-color: rgba(23, 114, 69, 0.05);
  background: rgba(23, 114, 69, 0.05);
}

.export-button {
  border: 1px solid #dfe3e8;
  background: #fff;
  color: #0D2B5A;
}
.export-button:hover {
  border-color: #177245;
  color: #177245;
}

/* =========================================================
   Logs Header
========================================================= */
.logs-card-header {
  border-bottom: 0;
}

/* =========================================================
   Table
========================================================= */
.table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.audit-table {
  width: 100%;
  min-width: 1050px;
  border-collapse: collapse;
}
.audit-table thead th {
  padding: 12px 18px;
  border-top: 1px solid #edf0f3;
  border-bottom: 1px solid #edf0f3;
  background: #fafbfc;
  color: #6e767e;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  text-align: left;
  white-space: nowrap;
}
.audit-table tbody tr {
  transition: background 0.2s ease;
}
.audit-table tbody tr:hover {
  background: rgba(23, 114, 69, 0.025);
}
.audit-table tbody tr + tr {
  border-top: 1px solid #edf0f3;
}
.audit-table tbody td {
  padding: 14px 18px;
  color: #606870;
  font-size: 14px;
  line-height: 1.5;
  vertical-align: middle;
}

/* =========================================================
   User
========================================================= */
.user-info {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 170px;
}

.user-avatar {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.1);
  color: #177245;
  font-size: 12px;
  font-weight: 700;
}
.user-avatar.client {
  background: rgba(13, 202, 240, 0.1);
  color: #0899b8;
}

.user-info strong {
  display: block;
  margin-bottom: 2px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;
}
.user-info span {
  display: block;
  color: #8a9198;
  font-size: 14px;
  line-height: 1.3;
}

/* =========================================================
   Action Badge
========================================================= */
.action-badge,
.module-badge {
  display: inline-flex;
  align-items: center;
  min-height: 25px;
  padding: 4px 8px;
  border-radius: 5px;
  font-size: 14px;
  line-height: 1;
  font-weight: 600;
  white-space: nowrap;
}

.action-badge.created {
  background: rgba(25, 135, 84, 0.09);
  color: #198754;
}
.action-badge.updated {
  background: rgba(13, 202, 240, 0.09);
  color: #0796b3;
}
.action-badge.login {
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
}
.action-badge.payment {
  background: rgba(212, 175, 55, 0.13);
  color: #9a7900;
}

.module-badge {
  background: #f2f4f6;
  color: #68717a;
}

/* =========================================================
   Description / Date
========================================================= */
.description {
  display: block;
  min-width: 170px;
  color: #596169;
}

.audit-table td .date {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  white-space: nowrap;
}
.audit-table td small {
  display: block;
  margin-top: 2px;
  color: #8a9198;
  font-size: 14px;
  line-height: 1.3;
}

/* =========================================================
   View Log
========================================================= */
.view-log {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #e1e5e9;
  border-radius: 7px;
  color: #0D2B5A;
  text-decoration: none;
  transition: all 0.2s ease;
}
.view-log:hover {
  border-color: #177245;
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
}
.view-log i {
  font-size: 16px;
}

/* =========================================================
   Pagination
========================================================= */
.logs-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 16px 18px;
  border-top: 1px solid #edf0f3;
}

.pagination-info {
  color: #7d858d;
  font-size: 14px;
}

.pagination-buttons {
  display: flex;
  align-items: center;
  gap: 5px;
}
.pagination-buttons button {
  min-width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 7px;
  border: 1px solid #e1e5e9;
  border-radius: 6px;
  background: #fff;
  color: #68717a;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.2s ease;
}
.pagination-buttons button:hover:not(:disabled), .pagination-buttons button.active {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.pagination-buttons button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.pagination-buttons span {
  padding: 0 3px;
  color: #899198;
  font-size: 14px;
}

/* =========================================================
   XXL
========================================================= */
@media (min-width: 1400px) and (max-width: 1700px) {
  .audit-logs-page {
    max-width: 1300px;
  }
  .audit-filter-grid {
    grid-template-columns: 2fr repeat(3, 1fr) auto;
  }
  .filter-field:nth-child(5) {
    grid-column: span 1;
  }
}
/* =========================================================
   XL
========================================================= */
@media (min-width: 1200px) and (max-width: 1399px) {
  .audit-logs-page {
    max-width: 1200px;
  }
  .audit-summary {
    grid-template-columns: repeat(2, 1fr);
  }
  .audit-filter-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .search-field {
    grid-column: span 2;
  }
}
/* =========================================================
   LG
========================================================= */
@media (min-width: 992px) and (max-width: 1199px) {
  .audit-logs-page {
    padding: 20px;
  }
  .audit-summary {
    grid-template-columns: repeat(2, 1fr);
  }
  .audit-filter-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .search-field {
    grid-column: 1/-1;
  }
  .filter-action {
    display: flex;
    justify-content: flex-start;
  }
}
/* =========================================================
   MD
========================================================= */
@media (min-width: 768px) and (max-width: 991px) {
  .audit-logs-page {
    padding: 18px;
  }
  .audit-summary {
    grid-template-columns: repeat(2, 1fr);
  }
  .audit-filter-grid {
    grid-template-columns: 1fr 1fr;
  }
  .search-field {
    grid-column: 1/-1;
  }
}
/* =========================================================
   XS
========================================================= */
@media (max-width: 767px) {
  .audit-logs-page {
    padding: 15px;
  }
  .audit-header {
    margin-bottom: 18px;
  }
  .audit-header-text h1 {
    font-size: 20px;
  }
  .audit-header-text p {
    font-size: 14px;
  }
  .audit-summary {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .summary-card {
    padding: 15px;
  }
  .summary-content strong {
    font-size: 18px;
  }
  .audit-card {
    margin-bottom: 15px;
    border-radius: 10px;
  }
  .audit-card-header,
  .logs-card-header {
    padding: 16px;
  }
  .audit-filter-body {
    padding: 16px;
  }
  .audit-filter-grid {
    grid-template-columns: 1fr;
  }
  .search-field {
    grid-column: auto;
  }
  .filter-action {
    width: 100%;
  }
  .filter-button {
    width: 100%;
  }
  .logs-card-header {
    align-items: flex-start;
  }
  .export-button {
    height: 38px;
    padding: 8px 11px;
  }
  .logs-pagination {
    flex-direction: column;
    align-items: flex-start;
  }
  .pagination-buttons {
    width: 100%;
    overflow-x: auto;
  }
}
/* =========================================================
   SM
========================================================= */
@media (min-width: 480px) and (max-width: 767px) {
  .audit-logs-page {
    padding: 14px;
  }
  .summary-card {
    gap: 11px;
  }
}
/* =========================================================
   Audit Details Page
========================================================= */
.audit-details-page {
  width: 100%;
  margin: 0 auto;
  padding: 24px;
}
.audit-details-page * {
  box-sizing: border-box;
}
.audit-details-page a,
.audit-details-page button,
.audit-details-page input,
.audit-details-page select,
.audit-details-page textarea {
  font-family: inherit;
}

/* =========================================================
   Header
========================================================= */
.details-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 24px;
}

.details-header-left {
  min-width: 0;
}

.back-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 15px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  text-decoration: none;
  transition: color 0.2s ease;
}
.back-button i {
  font-size: 16px;
}
.back-button:hover {
  color: #177245;
}

.details-title {
  display: flex;
  align-items: center;
  gap: 13px;
}

.details-title-icon {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 20px;
}

.details-title h1 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
}
.details-title p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/* =========================================================
   Layout
========================================================= */
.details-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  align-items: start;
  gap: 20px;
}

.details-main,
.details-sidebar {
  min-width: 0;
}

/* =========================================================
   Card
========================================================= */
.details-card {
  margin-bottom: 20px;
  overflow: hidden;
  border: 1px solid #e8ebef;
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 4px 18px rgba(16, 26, 35, 0.04);
}
.details-card:last-child {
  margin-bottom: 0;
}

.details-card-header {
  padding: 20px 22px;
  border-bottom: 1px solid #edf0f3;
}
.details-card-header h2 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 700;
}
.details-card-header p {
  margin: 0;
  color: #7b838b;
  font-size: 14px;
  line-height: 1.5;
}

.details-card-body {
  padding: 22px;
}
.details-card-body.no-padding {
  padding: 0;
}

/* =========================================================
   Badges
========================================================= */
.action-badge,
.module-badge {
  display: inline-flex;
  align-items: center;
  min-height: 25px;
  padding: 4px 9px;
  border-radius: 5px;
  font-size: 14px;
  line-height: 1;
  font-weight: 600;
  white-space: nowrap;
}

.action-badge.updated {
  background: rgba(13, 202, 240, 0.09);
  color: #0796b3;
}
.action-badge.created {
  background: rgba(25, 135, 84, 0.09);
  color: #198754;
}
.action-badge.deleted {
  background: rgba(220, 53, 69, 0.08);
  color: #dc3545;
}

.module-badge {
  background: #f2f4f6;
  color: #68717a;
}

/* =========================================================
   Info Grid
========================================================= */
.info-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px 30px;
}

.info-item {
  min-width: 0;
}

.info-label {
  display: block;
  margin-bottom: 6px;
  color: #858d95;
  font-size: 14px;
  line-height: 1.4;
}

.info-value {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.5;
  font-weight: 600;
  word-break: break-word;
}

/* =========================================================
   Description
========================================================= */
.description-box {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  padding: 16px;
  border: 1px solid rgba(23, 114, 69, 0.12);
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.035);
}

.description-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  font-size: 18px;
}

.description-box h3 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.description-box p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/* =========================================================
   Changes Table
========================================================= */
.changes-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.changes-table {
  width: 100%;
  min-width: 600px;
  border-collapse: collapse;
}
.changes-table thead th {
  padding: 12px 18px;
  border-bottom: 1px solid #edf0f3;
  background: #fafbfc;
  color: #6e767e;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  text-align: left;
}
.changes-table tbody tr + tr {
  border-top: 1px solid #edf0f3;
}
.changes-table tbody td {
  padding: 14px 18px;
  color: #626a72;
  font-size: 14px;
  line-height: 1.5;
  vertical-align: middle;
}
.changes-table tbody td:first-child {
  color: #0D2B5A;
  font-weight: 600;
}

.old-value {
  display: inline-block;
  padding: 4px 7px;
  border-radius: 5px;
  background: rgba(220, 53, 69, 0.07);
  color: #dc3545;
}

.new-value {
  display: inline-block;
  padding: 4px 7px;
  border-radius: 5px;
  background: rgba(25, 135, 84, 0.08);
  color: #198754;
}

/* =========================================================
   Technical Information
========================================================= */
.technical-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.technical-item {
  padding: 14px;
  border: 1px solid #edf0f3;
  border-radius: 8px;
  background: #fafbfc;
}
.technical-item span {
  display: block;
  margin-bottom: 5px;
  color: #858d95;
  font-size: 14px;
  line-height: 1.4;
}
.technical-item strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.5;
  font-weight: 600;
  word-break: break-word;
}

/* =========================================================
   Performed User
========================================================= */
.performed-user {
  display: flex;
  align-items: center;
  gap: 11px;
  padding-bottom: 18px;
  border-bottom: 1px solid #edf0f3;
}

.user-avatar {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(13, 202, 240, 0.1);
  color: #0796b3;
  font-size: 13px;
  font-weight: 700;
}

.performed-user strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.performed-user span {
  display: block;
  color: #858d95;
  font-size: 14px;
  line-height: 1.4;
  word-break: break-word;
}

/* =========================================================
   Sidebar Info
========================================================= */
.sidebar-info {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding-top: 17px;
}
.sidebar-info > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
.sidebar-info span {
  color: #858d95;
  font-size: 14px;
}
.sidebar-info strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  text-align: right;
}

/* =========================================================
   Related Resource
========================================================= */
.resource-box {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px;
  border: 1px solid #edf0f3;
  border-radius: 9px;
  background: #fafbfc;
}

.resource-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 18px;
}

.resource-box span {
  display: block;
  margin-bottom: 3px;
  color: #858d95;
  font-size: 14px;
}
.resource-box strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.resource-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 13px;
  color: #177245;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  text-decoration: none;
}
.resource-link i {
  font-size: 16px;
}
.resource-link:hover {
  color: rgba(23, 114, 69, 0.8);
}

/* =========================================================
   Status
========================================================= */
.status-box {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 13px;
  border-radius: 9px;
  background: rgba(25, 135, 84, 0.06);
}

.status-dot {
  width: 9px;
  height: 9px;
  flex: 0 0 9px;
  margin-top: 5px;
  border-radius: 50%;
  background: #198754;
}

.status-box strong {
  display: block;
  margin-bottom: 3px;
  color: #198754;
  font-size: 14px;
  font-weight: 600;
}
.status-box span:last-child {
  display: block;
  color: #707980;
  font-size: 14px;
  line-height: 1.5;
}

/* =========================================================
   XXL
========================================================= */
@media (min-width: 1400px) and (max-width: 1700px) {
  .details-layout {
    grid-template-columns: minmax(0, 1fr) 320px;
  }
}
/* =========================================================
   XL
========================================================= */
@media (min-width: 1200px) and (max-width: 1399px) {
  .details-layout {
    grid-template-columns: minmax(0, 1fr) 300px;
  }
}
/* =========================================================
   LG
========================================================= */
@media (min-width: 992px) and (max-width: 1199px) {
  .audit-details-page {
    padding: 20px;
  }
  .details-layout {
    grid-template-columns: 1fr;
  }
  .details-sidebar {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 15px;
  }
  .details-sidebar .details-card {
    margin-bottom: 0;
  }
}
/* =========================================================
   MD
========================================================= */
@media (min-width: 768px) and (max-width: 991px) {
  .audit-details-page {
    padding: 18px;
  }
  .details-header {
    align-items: flex-start;
  }
  .details-sidebar {
    grid-template-columns: 1fr 1fr;
  }
  .details-sidebar .details-card:last-child {
    grid-column: 1/-1;
  }
}
/* =========================================================
   XS
========================================================= */
@media (max-width: 767px) {
  .audit-details-page {
    padding: 15px;
  }
  .details-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 18px;
  }
  .details-title h1 {
    font-size: 20px;
  }
  .details-title p {
    font-size: 14px;
  }
  .details-title-icon {
    width: 40px;
    height: 40px;
    flex-basis: 40px;
    font-size: 18px;
  }
  .details-card {
    margin-bottom: 15px;
    border-radius: 10px;
  }
  .details-card-header {
    padding: 16px;
  }
  .details-card-header h2 {
    font-size: 17px;
  }
  .details-card-header p {
    font-size: 14px;
  }
  .details-card-body {
    padding: 16px;
  }
  .info-grid,
  .technical-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .details-sidebar {
    grid-template-columns: 1fr;
  }
  .details-sidebar .details-card:last-child {
    grid-column: auto;
  }
  .description-box {
    padding: 13px;
  }
  .changes-table {
    min-width: 560px;
  }
  .sidebar-info > div {
    align-items: flex-start;
  }
}
/* =========================================================
   SM
========================================================= */
@media (min-width: 480px) and (max-width: 767px) {
  .audit-details-page {
    padding: 14px;
  }
}
.reports-page {
  font-family: "Poppins", sans-serif;
  color: #555555;
}
.reports-page .page-header {
