  align-items: center;
  justify-content: space-between;
  margin: 20px;
  padding: 18px;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.05);
}
.payment-details-page .amount-highlight span {
  color: #555555;
  font-size: 14px;
}
.payment-details-page .amount-highlight strong {
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 24px;
  font-weight: 700;
}
.payment-details-page .payment-method {
  display: inline-flex;
  align-items: center;
  gap: 9px;
}
.payment-details-page .payment-method i {
  color: #0D2B5A;
  font-size: 20px;
}
.payment-details-page .payment-method span {
  color: #555555;
  font-size: 14px;
}
.payment-details-page .related-order {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 20px;
  padding: 16px;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #F2F4F7;
}
.payment-details-page .order-icon {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 7px;
  background: #fff;
  color: #177245;
  font-size: 18px;
}
.payment-details-page .order-content {
  flex: 1;
}
.payment-details-page .order-content span {
  display: block;
  margin-bottom: 3px;
  color: #555555;
  font-size: 14px;
}
.payment-details-page .order-content strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 16px;
  font-weight: 700;
}
.payment-details-page .order-content p {
  margin: 0;
  color: #555555;
  font-size: 14px;
}
.payment-details-page .view-order-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}
.payment-details-page .view-order-btn:hover {
  color: rgba(23, 114, 69, 0.8);
}
.payment-details-page .order-status {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0 10px;
  border-radius: 5px;
  background: rgba(255, 193, 7, 0.13);
  color: rgba(255, 193, 7, 0.18);
  font-size: 14px;
  font-weight: 600;
}
.payment-details-page .payment-timeline-card {
  margin-bottom: 20px;
}
.payment-details-page .payment-timeline {
  padding: 20px 24px;
}
.payment-details-page .timeline-item {
  position: relative;
  display: flex;
  gap: 14px;
  min-height: 86px;
}
.payment-details-page .timeline-item:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 38px;
  left: 16px;
  width: 1px;
  height: calc(100% - 12px);
  background: #ddd;
}
.payment-details-page .timeline-icon {
  position: relative;
  z-index: 1;
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(25, 135, 84, 0.2);
  border-radius: 50%;
  background: rgba(25, 135, 84, 0.09);
  color: #198754;
  font-size: 14px;
}
.payment-details-page .timeline-content strong {
  display: block;
  margin-bottom: 4px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.3;
}
.payment-details-page .timeline-content p {
  margin: 0 0 5px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}
.payment-details-page .timeline-content span {
  color: rgba(85, 85, 85, 0.7);
  font-size: 14px;
}
@media (max-width: 991px) {
  .payment-details-page .page-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .payment-details-page .page-header-actions {
    width: 100%;
  }
  .payment-details-page .payment-summary-card {
    align-items: flex-start;
    flex-direction: column;
  }
  .payment-details-page .payment-summary-meta {
    width: 100%;
    justify-content: space-between;
  }
  .payment-details-page .details-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 767px) {
  .payment-details-page .payment-summary-main {
    align-items: flex-start;
  }
  .payment-details-page .payment-summary-content h2 {
    font-size: 20px;
  }
  .payment-details-page .payment-summary-meta {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
  }
  .payment-details-page .details-card-header {
    padding: 18px;
  }
  .payment-details-page .details-list {
    padding: 6px 18px;
  }
  .payment-details-page .customer-profile {
    padding: 18px;
  }
  .payment-details-page .customer-contact-list {
    padding: 0 18px 18px;
  }
  .payment-details-page .related-order {
    align-items: flex-start;
    flex-wrap: wrap;
    margin: 18px;
  }
  .payment-details-page .view-order-btn {
    width: 100%;
    padding-top: 8px;
  }
  .payment-details-page .payment-timeline {
    padding: 20px 18px;
  }
}
@media (max-width: 480px) {
  .payment-details-page .payment-summary-card {
    padding: 18px;
  }
  .payment-details-page .payment-summary-main {
    gap: 12px;
  }
  .payment-details-page .payment-status-icon {
    width: 46px;
    height: 46px;
    flex-basis: 46px;
  }
  .payment-details-page .detail-item {
    align-items: flex-start;
    flex-direction: column;
    gap: 6px;
  }
  .payment-details-page .detail-value {
    text-align: left;
  }
  .payment-details-page .amount-highlight strong {
    font-size: 20px;
  }
}

/*================================*
* Roles Page
*=================================*/
.roles-page {
  width: 100%;
}

/*================================*
* Page Header
*=================================*/
.roles-page__header {
  margin-bottom: 24px;
}

.roles-page__header-content {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
}
@media (min-width: 768px) and (max-width: 991px) {
  .roles-page__header-content {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }
}

.roles-page__heading .roles-page__eyebrow {
  display: inline-block;
  margin-bottom: 7px;
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.roles-page__heading h1 {
  margin: 0 0 6px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 24px;
  font-weight: 700;
  line-height: 1.25;
}
.roles-page__heading p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*================================*
* Header Action
*=================================*/
.roles-page__actions {
  flex-shrink: 0;
}
@media (min-width: 768px) and (max-width: 991px) {
  .roles-page__actions {
    width: 100%;
  }
}

.roles-primary-btn {
  min-height: 42px;
  padding: 0 17px;
  border: 1px solid #177245;
  border-radius: 7px;
  background: #177245;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  text-decoration: none;
  transition: all 0.2s ease;
}
.roles-primary-btn i {
  display: block;
  color: #fff;
  font-size: 16px;
  line-height: 1;
}
.roles-primary-btn:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
  color: #fff;
}
@media (min-width: 768px) and (max-width: 991px) {
  .roles-primary-btn {
    width: 100%;
  }
}

/*================================*
* Alerts
*=================================*/
.roles-alert {
  margin-bottom: 18px;
  padding: 14px 16px;
  border-radius: 8px;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 14px;
  line-height: 1.5;
}
.roles-alert i {
  flex: 0 0 auto;
  margin-top: 2px;
  font-size: 17px;
  line-height: 1;
}

.roles-alert--success {
  border: 1px solid rgba(23, 114, 69, 0.14);
  background: rgba(23, 114, 69, 0.055);
  color: rgba(23, 114, 69, 0.05);
}

.roles-alert--danger {
  border: 1px solid rgba(220, 38, 38, 0.14);
  background: rgba(220, 38, 38, 0.045);
  color: #b91c1c;
}

/*================================*
* Statistics
*=================================*/
.roles-stats {
  margin-bottom: 20px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}
@media (min-width: 992px) and (max-width: 1199px) {
  .roles-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 767px) {
  .roles-stats {
    grid-template-columns: 1fr;
    gap: 10px;
  }
}

/*================================*
* Statistic Card
*=================================*/
.role-stat-card {
  min-height: 96px;
  padding: 16px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.035);
  display: flex;
  align-items: center;
  gap: 13px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}
.role-stat-card:hover {
  border-color: rgba(23, 114, 69, 0.12);
  box-shadow: 0 5px 18px rgba(16, 26, 35, 0.055);
  transform: translateY(-1px);
}

/*================================*
* Statistic Icon
*=================================*/
.role-stat-card__icon {
  width: 42px;
  height: 42px;
  border-radius: 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 42px;
}
.role-stat-card__icon i {
  font-size: 20px;
  line-height: 1;
}

.role-stat-card__icon--total {
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
}

.role-stat-card__icon--users {
  background: rgba(13, 202, 240, 0.09);
  color: #0dcaf0;
}

.role-stat-card__icon--permissions {
  background: rgba(25, 135, 84, 0.09);
  color: #198754;
}

.role-stat-card__icon--empty {
  background: rgba(255, 193, 7, 0.1);
  color: #ffc107;
}

/*================================*
* Statistic Content
*=================================*/
.role-stat-card__content {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.role-stat-card__content span {
  margin-bottom: 3px;
  color: #555555;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
}

.role-stat-card__content strong {
  margin-bottom: 3px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 22px;
  font-weight: 600;
  line-height: 1.2;
}

.role-stat-card__content small {
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

/*================================*
* Table Card
*=================================*/
.roles-table-card {
  width: 100%;
  overflow: hidden;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.035);
}
@media (min-width: 768px) and (max-width: 991px) {
  .roles-table-card {
    border-radius: 10px;
  }
}

/*================================*
* Table Card Header
*=================================*/
.roles-table-card__header {
  min-height: 76px;
  padding: 18px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.07);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
@media (max-width: 767px) {
  .roles-table-card__header {
    align-items: flex-start;
    flex-direction: column;
    padding: 16px;
  }
}

.roles-table-card__heading h2 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.roles-table-card__heading p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*================================*
* Role Count
*=================================*/
.roles-count {
  min-height: 32px;
  padding: 0 11px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 6px;
  background: rgba(16, 26, 35, 0.025);
  color: #555555;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

/*================================*
* Table Wrapper
*=================================*/
.roles-table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

/*================================*
* Roles Table
*=================================*/
.roles-table {
  width: 100%;
  min-width: 900px;
  border-collapse: collapse;
}
.roles-table th {
  padding: 14px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.07);
  background: rgba(16, 26, 35, 0.018);
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  text-align: left;
  white-space: nowrap;
}
.roles-table td {
  padding: 16px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
  vertical-align: middle;
}
.roles-table tbody tr {
  transition: background-color 0.2s ease;
}
.roles-table tbody tr:hover {
  background: rgba(23, 114, 69, 0.018);
}
.roles-table tbody tr:last-child td {
  border-bottom: 0;
}

/*================================*
* Role Profile
*=================================*/
.role-profile {
  display: flex;
  align-items: center;
  gap: 11px;
}

.role-profile__icon {
  width: 38px;
  height: 38px;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 38px;
}
.role-profile__icon i {
  font-size: 18px;
  line-height: 1;
}

.role-profile__info {
  min-width: 0;
}

.role-profile__name {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
  text-decoration: none;
  transition: color 0.2s ease;
}
.role-profile__name:hover {
  color: #177245;
}

.role-profile__info > span {
  display: block;
  color: rgba(85, 85, 85, 0.8);
  font-size: 14px;
  line-height: 1.3;
}

/*================================*
* Role Slug
*=================================*/
.role-slug {
  display: inline-flex;
  padding: 6px 9px;
  border: 1px solid rgba(16, 26, 35, 0.06);
  border-radius: 5px;
  background: rgba(16, 26, 35, 0.025);
  color: #555555;
  font-family: monospace;
  font-size: 14px;
  line-height: 1.3;
}

/*================================*
* Role Count In Table
*=================================*/
.role-count {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.role-count i {
  font-size: 16px;
  line-height: 1;
}

.role-count strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
}

.role-count small {
  color: #555555;
  font-size: 14px;
  line-height: 1;
}

.role-count--users i {
  color: #177245;
}

.role-count--permissions i {
  color: #198754;
}

/*================================*
* Role Date
*=================================*/
.role-date {
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

/*================================*
* Actions
*=================================*/
.role-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}

.role-view-btn,
.role-edit-btn,
.role-delete-btn {
  width: 34px;
  height: 34px;
  margin: 0;
  padding: 0;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.2s ease;
}
.role-view-btn i,
.role-edit-btn i,
.role-delete-btn i {
  display: block;
  font-size: 16px;
  line-height: 1;
}

/*================================*
* View
*=================================*/
.role-view-btn {
  border: 1px solid rgba(23, 114, 69, 0.15);
  background: rgba(23, 114, 69, 0.045);
  color: #177245;
}
.role-view-btn:hover {
  border-color: rgba(23, 114, 69, 0.25);
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
}

/*================================*
* Edit
*=================================*/
.role-edit-btn {
  border: 1px solid rgba(13, 202, 240, 0.15);
  background: rgba(13, 202, 240, 0.045);
  color: #0dcaf0;
}
.role-edit-btn:hover {
  border-color: rgba(13, 202, 240, 0.25);
  background: rgba(13, 202, 240, 0.09);
  color: #0dcaf0;
}

/*================================*
* Delete
*=================================*/
.role-delete-btn {
  border: 1px solid rgba(220, 38, 38, 0.15);
  background: rgba(220, 38, 38, 0.045);
  color: #dc2626;
}
.role-delete-btn:hover {
  border-color: rgba(220, 38, 38, 0.25);
  background: rgba(220, 38, 38, 0.08);
  color: #dc2626;
}

.role-delete-btn--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.role-delete-btn--disabled:hover {
  border-color: rgba(220, 38, 38, 0.15);
  background: rgba(220, 38, 38, 0.045);
  color: #dc2626;
}

.role-delete-form {
  margin: 0;
  padding: 0;
  display: inline-flex;
}

/*================================*
* Table Footer
*=================================*/
.roles-table-card__footer {
  min-height: 62px;
  padding: 13px 20px;
  border-top: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
@media (max-width: 767px) {
  .roles-table-card__footer {
    align-items: flex-start;
    flex-direction: column;
  }
}

/*================================*
* Pagination Info
*=================================*/
.roles-pagination-info {
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.roles-pagination-info strong {
  color: #0D2B5A;
  font-weight: 600;
}

/*================================*
* Pagination
*=================================*/
.roles-pagination nav {
  display: flex;
}
.roles-pagination .pagination {
  margin: 0;
  display: flex;
  align-items: center;
  gap: 5px;
  list-style: none;
}
.roles-pagination .page-item .page-link {
  min-width: 34px;
  height: 34px;
  padding: 0 8px;
  border: 1px solid rgba(16, 26, 35, 0.08);
  border-radius: 6px;
  background: #fff;
  color: #555555;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
  transition: all 0.2s ease;
}
.roles-pagination .page-item .page-link:hover {
  border-color: rgba(23, 114, 69, 0.25);
  background: rgba(23, 114, 69, 0.05);
  color: #177245;
}
.roles-pagination .page-item.active .page-link {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.roles-pagination .page-item.disabled .page-link {
  opacity: 0.4;
  cursor: not-allowed;
}

/*================================*
* Empty State
*=================================*/
.roles-empty {
  min-height: 330px;
  padding: 50px 25px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.roles-empty__content {
  max-width: 420px;
  display: flex;
  align-items: center;
  flex-direction: column;
}

/*================================*
* Empty Icon
*=================================*/
.roles-empty__icon {
  width: 62px;
  height: 62px;
  margin-bottom: 16px;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.roles-empty__icon i {
  font-size: 24px;
  line-height: 1;
}

/*================================*
* Empty Text
*=================================*/
.roles-empty__content h3 {
  margin: 0 0 8px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.roles-empty__content p {
  margin: 0 0 20px;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*================================*
* XL
*=================================*/
@media (min-width: 1200px) and (max-width: 1399px) {
  .roles-page__header {
    margin-bottom: 22px;
  }
  .roles-stats {
    gap: 12px;
  }
  .role-stat-card {
    padding: 15px;
  }
  .roles-table-card__header {
    padding: 17px 18px;
