  min-height: 32px;
  padding: 0 10px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 6px;
  background: rgba(16, 26, 35, 0.025);
  color: #0D2B5A;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

/*================================*
* Role Information
*=================================*/
.role-details-information {
  padding: 6px 20px 20px;
}

.role-details-information__item {
  min-height: 62px;
  padding: 14px 0;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
.role-details-information__item:last-child {
  border-bottom: 0;
}
.role-details-information__item > span {
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}
.role-details-information__item > strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  text-align: right;
}
.role-details-information__item > code {
  padding: 6px 9px;
  border: 1px solid rgba(16, 26, 35, 0.06);
  border-radius: 5px;
  background: rgba(16, 26, 35, 0.025);
  color: #555555;
  font-family: monospace;
  font-size: 14px;
}
@media (max-width: 767px) {
  .role-details-information__item {
    align-items: flex-start;
    flex-direction: column;
    gap: 7px;
  }
  .role-details-information__item > strong {
    text-align: left;
  }
}

/*================================*
* Permissions List
*=================================*/
.role-permissions-list {
  padding: 8px 20px 20px;
  display: flex;
  flex-direction: column;
}

.role-permission-item {
  padding: 14px 0;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  align-items: flex-start;
  gap: 11px;
}

.role-permission-item__icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: rgba(25, 135, 84, 0.09);
  color: #198754;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 36px;
}
.role-permission-item__icon i {
  font-size: 17px;
}

.role-permission-item__content {
  min-width: 0;
}
.role-permission-item__content strong {
  display: block;
  margin-bottom: 5px;
  color: #0D2B5A;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
}
.role-permission-item__content code {
  display: inline-block;
  margin-bottom: 5px;
  padding: 4px 7px;
  border: 1px solid rgba(16, 26, 35, 0.06);
  border-radius: 5px;
  background: rgba(16, 26, 35, 0.025);
  color: #555555;
  font-family: monospace;
  font-size: 14px;
}
.role-permission-item__content p,
.role-permission-item__content small {
  display: block;
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*================================*
* Permissions Footer
*=================================*/
.role-details-permissions-footer {
  padding: 14px 20px;
  border-top: 1px solid rgba(16, 26, 35, 0.07);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
@media (max-width: 767px) {
  .role-details-permissions-footer {
    padding: 14px 16px;
    align-items: stretch;
    flex-direction: column;
  }
}

.role-details-permissions-footer__info {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}
.role-details-permissions-footer__info i {
  color: #177245;
  font-size: 16px;
}

.role-details-manage-permissions-btn {
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid #177245;
  border-radius: 7px;
  background: #177245;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: background-color 0.2s ease, border-color 0.2s ease;
}
.role-details-manage-permissions-btn i {
  font-size: 16px;
}
.role-details-manage-permissions-btn:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
  color: #fff;
}
@media (max-width: 767px) {
  .role-details-manage-permissions-btn {
    width: 100%;
  }
}

/*================================*
* Assigned Users Card
*=================================*/
.role-details-card--users {
  margin-bottom: 20px;
}

/*================================*
* Users Table
*=================================*/
.role-users-table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.role-users-table {
  width: 100%;
  min-width: 760px;
  border-collapse: collapse;
}
.role-users-table th {
  padding: 14px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.07);
  background: rgba(16, 26, 35, 0.018);
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  text-align: left;
  white-space: nowrap;
}
.role-users-table td {
  padding: 15px 20px;
