  font-size: 14px;
  line-height: 1.5;
  vertical-align: middle;
}
.role-users-table tbody tr {
  transition: background-color 0.2s ease;
}
.role-users-table tbody tr:hover {
  background: rgba(23, 114, 69, 0.018);
}
.role-users-table tbody tr:last-child td {
  border-bottom: 0;
}

/*================================*
* User Profile
*=================================*/
.role-user-profile {
  display: flex;
  align-items: center;
  gap: 10px;
}

.role-user-profile__avatar {
  width: 38px;
  height: 38px;
  overflow: hidden;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 38px;
}
.role-user-profile__avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.role-user-profile__avatar span {
  font-size: 14px;
  font-weight: 600;
}

.role-user-profile__info strong {
  color: #0D2B5A;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
}

/*================================*
* User Email
*=================================*/
.role-user-email {
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

/*================================*
* User Status
*=================================*/
.role-user-status {
  min-height: 30px;
  padding: 0 10px;
  border-radius: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  text-transform: capitalize;
}

.role-user-status--active {
  border: 1px solid rgba(25, 135, 84, 0.15);
  background: rgba(25, 135, 84, 0.07);
  color: #198754;
}

.role-user-status--inactive {
  border: 1px solid rgba(255, 193, 7, 0.15);
  background: rgba(255, 193, 7, 0.07);
  color: #ffc107;
}

.role-user-status--suspended {
  border: 1px solid rgba(220, 38, 38, 0.15);
  background: rgba(220, 38, 38, 0.06);
  color: #dc2626;
}

/*================================*
* User Date
*=================================*/
.role-user-date {
  color: rgba(85, 85, 85, 0.8);
  font-size: 14px;
}

/*================================*
* User View Button
*=================================*/
.role-user-view-btn {
  width: 34px;
  height: 34px;
  border: 1px solid rgba(16, 26, 35, 0.08);
  border-radius: 6px;
  background: #fff;
  color: #555555;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  text-decoration: none;
  transition: all 0.2s ease;
}
.role-user-view-btn:hover {
  border-color: #177245;
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
}

/*================================*
* Empty State
*=================================*/
.role-details-empty {
  min-height: 230px;
  padding: 35px 20px;
