  align-items: center;
  justify-content: center;
  flex-direction: column;
  text-align: center;
}

.role-details-empty__icon {
  width: 54px;
  height: 54px;
  margin-bottom: 14px;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.09);
