  cursor: pointer;
  transition: 0.2s ease;
}
.role-permissions-tool-btn i {
  font-size: 15px;
}
.role-permissions-tool-btn:hover {
  border-color: #177245;
  color: #177245;
  background: rgba(23, 114, 69, 0.025);
}
@media (max-width: 767px) {
  .role-permissions-tool-btn {
    flex: 1;
  }
}

/*================================*
* Permission List
*=================================*/
.role-permissions-list {
  padding: 18px 20px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
@media (min-width: 768px) and (max-width: 991px) {
  .role-permissions-list {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 767px) {
  .role-permissions-list {
    padding: 15px;
  }
}

/*================================*
* Permission Item
*=================================*/
.role-permission-item {
  position: relative;
  min-height: 76px;
  padding: 13px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 8px;
  background: #fff;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
  transition: border-color 0.2s ease, background-color 0.2s ease, box-shadow 0.2s ease;
}
.role-permission-item:hover {
  border-color: rgba(23, 114, 69, 0.3);
  background: rgba(23, 114, 69, 0.015);
}
.role-permission-item input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.role-permission-item:has(input:checked) {
  border-color: rgba(23, 114, 69, 0.35);
  background: rgba(23, 114, 69, 0.035);
  box-shadow: 0 2px 8px rgba(23, 114, 69, 0.05);
}
@media (max-width: 767px) {
  .role-permission-item {
    padding: 12px;
  }
}

.role-permission-item__checkbox {
  width: 22px;
  height: 22px;
  margin-top: 1px;
  border: 1px solid #ddd;
  border-radius: 5px;
  background: #fff;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 22px;
  transition: 0.2s ease;
}
.role-permission-item__checkbox i {
  opacity: 0;
  font-size: 14px;
  line-height: 1;
}

.role-permission-item:has(input:checked) .role-permission-item__checkbox {
  border-color: #177245;
  background: #177245;
}
.role-permission-item:has(input:checked) .role-permission-item__checkbox i {
  opacity: 1;
}

.role-permission-item__content {
  min-width: 0;
}
.role-permission-item__content strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
}
.role-permission-item__content > span {
  display: block;
  margin-bottom: 4px;
  color: #177245;
  font-size: 14px;
  line-height: 1.35;
  word-break: break-word;
}
.role-permission-item__content small {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.45;
}

/*================================*
* Empty State
*=================================*/
.role-permissions-empty {
  grid-column: 1/-1;
  padding: 45px 20px;
  text-align: center;
}

.role-permissions-empty__icon {
  width: 52px;
  height: 52px;
  margin: 0 auto 12px;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  display: flex;
  align-items: center;
  justify-content: center;
}
.role-permissions-empty__icon i {
  font-size: 22px;
}

.role-permissions-empty h3 {
  margin: 0 0 6px;
  color: #0D2B5A;
  font-size: 18px;
  font-weight: 600;
}
.role-permissions-empty p {
  max-width: 450px;
  margin: 0 auto 16px;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

.role-permissions-empty__btn {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 7px;
  background: #177245;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s ease;
}
.role-permissions-empty__btn i {
  font-size: 16px;
}
.role-permissions-empty__btn:hover {
  background: rgba(23, 114, 69, 0.7);
  color: #fff;
}

/*================================*
* Card Footer
*=================================*/
.role-permissions-card__footer {
  min-height: 66px;
  padding: 12px 20px;
  border-top: 1px solid rgba(16, 26, 35, 0.07);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
@media (max-width: 767px) {
  .role-permissions-card__footer {
    padding: 14px 15px;
    align-items: stretch;
    flex-direction: column;
  }
}

.role-permissions-selected {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #555555;
  font-size: 14px;
}
.role-permissions-selected i {
  color: #177245;
  font-size: 16px;
}
.role-permissions-selected strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

/*================================*
* Form Actions
*=================================*/
.role-permissions-form-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
@media (max-width: 767px) {
  .role-permissions-form-actions {
    width: 100%;
  }
}

.role-permissions-cancel-btn,
.role-permissions-save-btn {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s ease;
}
.role-permissions-cancel-btn i,
.role-permissions-save-btn i {
  font-size: 16px;
}
@media (max-width: 767px) {
  .role-permissions-cancel-btn,
  .role-permissions-save-btn {
    flex: 1;
  }
}

.role-permissions-cancel-btn {
  border: 1px solid #ddd;
  background: #fff;
  color: #0D2B5A;
}
.role-permissions-cancel-btn:hover {
  border-color: #177245;
  color: #177245;
}

.role-permissions-save-btn {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
  cursor: pointer;
}
.role-permissions-save-btn:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
}

/*================================*
* Responsive
*=================================*/
@media (min-width: 768px) and (max-width: 991px) {
  .role-permissions-list {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 767px) {
  .role-permissions-page__actions {
    width: 100%;
  }
  .role-permissions-role-card {
    align-items: flex-start;
  }
  .role-permissions-role-card__content {
    flex: 1 1 calc(100% - 65px);
  }
  .role-permissions-role-card__stats {
    flex-basis: 100%;
  }
  .role-permissions-card__tools {
    width: 100%;
  }
  .role-permissions-tool-btn {
    flex: 1;
  }
  .role-permissions-form-actions {
    width: 100%;
  }
  .role-permissions-cancel-btn,
  .role-permissions-save-btn {
    flex: 1;
  }
}
/*================================*
* Permission Page
*=================================*/
.permission-page {
  width: 100%;
}

/*================================*
* Page Header
*=================================*/
.permission-page__header {
  margin-bottom: 24px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
}
@media (min-width: 768px) and (max-width: 991px) {
  .permission-page__header {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }
}

.permission-page__heading .permission-page__eyebrow {
  display: inline-block;
  margin-bottom: 7px;
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.permission-page__heading h1 {
  margin: 0 0 6px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 24px;
  font-weight: 700;
  line-height: 1.25;
}
.permission-page__heading p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*================================*
* Header Actions
*=================================*/
.permission-page__actions {
  flex-shrink: 0;
}
@media (min-width: 768px) and (max-width: 991px) {
  .permission-page__actions {
    width: 100%;
  }
}

.permission-primary-btn {
  min-height: 42px;
  padding: 0 16px;
  border: 1px solid #177245;
  border-radius: 7px;
  background: #177245;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  text-decoration: none;
  transition: all 0.2s ease;
}
.permission-primary-btn i {
  font-size: 17px;
  line-height: 1;
}
.permission-primary-btn:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
  color: #fff;
}
@media (min-width: 768px) and (max-width: 991px) {
  .permission-primary-btn {
    width: 100%;
  }
}

/*================================*
* Permission Card
*=================================*/
.permission-card {
  width: 100%;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.035);
  overflow: hidden;
}

/*================================*
* Card Header
*=================================*/
.permission-card__header {
  min-height: 80px;
  padding: 18px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.07);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
@media (max-width: 767px) {
  .permission-card__header {
    align-items: flex-start;
    flex-direction: column;
    gap: 14px;
  }
}

.permission-card__title {
  display: flex;
  align-items: center;
  gap: 12px;
}

.permission-card__icon {
  width: 42px;
  height: 42px;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 42px;
}
.permission-card__icon i {
  font-size: 20px;
  line-height: 1;
}

.permission-card__title h2 {
  margin: 0 0 4px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.permission-card__title p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*================================*
* Permission Count
*=================================*/
.permission-card__count {
  display: flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
}
.permission-card__count span {
  min-width: 34px;
  min-height: 32px;
  padding: 0 9px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 6px;
  background: rgba(16, 26, 35, 0.025);
  color: #0D2B5A;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
}
.permission-card__count small {
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

/*================================*
* Table Wrapper
*=================================*/
.permission-table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

/*================================*
* Table
*=================================*/
.permission-table {
  width: 100%;
  min-width: 950px;
  border-collapse: collapse;
}
.permission-table th {
  padding: 14px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.07);
  background: rgba(16, 26, 35, 0.018);
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  text-align: left;
  white-space: nowrap;
}
.permission-table td {
  padding: 15px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
  vertical-align: middle;
}
.permission-table tbody tr {
  transition: background-color 0.2s ease;
}
.permission-table tbody tr:hover {
  background: rgba(23, 114, 69, 0.018);
}
.permission-table tbody tr:last-child td {
  border-bottom: 0;
}

/*================================*
* Actions Column
*=================================*/
.permission-table__actions-column {
  width: 120px;
  text-align: right !important;
}

/*================================*
* Permission Name
*=================================*/
.permission-name {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 190px;
}

.permission-name__icon {
  width: 38px;
  height: 38px;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 38px;
}
.permission-name__icon i {
  font-size: 18px;
  line-height: 1;
}

.permission-name__content {
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.permission-name__content strong {
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.35;
  white-space: nowrap;
}
.permission-name__content span {
  color: rgba(85, 85, 85, 0.1);
  font-size: 14px;
  line-height: 1.3;
}

/*================================*
* Permission Slug
*=================================*/
.permission-slug {
  display: inline-block;
  max-width: 210px;
  padding: 6px 8px;
  border: 1px solid rgba(16, 26, 35, 0.06);
  border-radius: 5px;
  background: rgba(16, 26, 35, 0.025);
  color: #555555;
  font-family: monospace;
  font-size: 14px;
  line-height: 1.3;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*================================*
* Description
*=================================*/
.permission-description {
  display: block;
  max-width: 270px;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

.permission-description--empty {
  color: rgba(85, 85, 85, 0.18);
  font-style: italic;
}

/*================================*
* Role Count
*=================================*/
.permission-role-count {
  min-height: 32px;
  padding: 0 9px;
  border: 1px solid rgba(13, 202, 240, 0.12);
  border-radius: 6px;
  background: rgba(13, 202, 240, 0.06);
  color: #0dcaf0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}
.permission-role-count i {
  font-size: 16px;
}

/*================================*
* Date
*=================================*/
.permission-date {
  color: #555555;
  font-size: 14px;
  white-space: nowrap;
}

/*================================*
* Actions
*=================================*/
.permission-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}

.permission-delete-form {
  margin: 0;
  padding: 0;
}

.permission-action {
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 6px;
  background: #fff;
  color: #555555;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.2s ease;
}
.permission-action i {
  font-size: 16px;
  line-height: 1;
}

/*================================*
* View Action
*=================================*/
.permission-action--view:hover {
  border-color: rgba(13, 202, 240, 0.2);
  background: rgba(13, 202, 240, 0.07);
  color: #0dcaf0;
}

/*================================*
* Edit Action
*=================================*/
.permission-action--edit:hover {
  border-color: rgba(23, 114, 69, 0.2);
  background: rgba(23, 114, 69, 0.07);
  color: #177245;
}

/*================================*
* Delete Action
*=================================*/
.permission-action--delete:hover {
  border-color: rgba(220, 38, 38, 0.2);
  background: rgba(220, 38, 38, 0.06);
  color: #dc2626;
}

/*================================*
* Pagination
*=================================*/
.permission-pagination {
  width: 100%;
  padding: 16px 20px;
  border-top: 1px solid rgba(16, 26, 35, 0.055);
  background: #fff;
  box-sizing: border-box;
  /*
  |--------------------------------------------------------------------------
  | Laravel Pagination Navigation
  |--------------------------------------------------------------------------
  */
}
.permission-pagination nav {
  width: 100%;
  display: block !important;
  margin: 0;
}
.permission-pagination {
  /*
  |--------------------------------------------------------------------------
  | Desktop Pagination Wrapper
  |--------------------------------------------------------------------------
  |
  | Laravel generates:
  |
  | 1st div = mobile pagination
  | 2nd div = desktop pagination
  |
  */
}
.permission-pagination nav > div:nth-child(1) {
  display: none !important;
}
.permission-pagination nav > div:nth-child(2) {
  width: 100%;
  min-height: 36px;
  display: flex !important;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin: 0 !important;
  box-sizing: border-box;
}
.permission-pagination {
  /*
  |--------------------------------------------------------------------------
  | Result Information
  |--------------------------------------------------------------------------
  */
}
.permission-pagination nav > div:nth-child(2) > div:first-child {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0 !important;
}
.permission-pagination nav > div:nth-child(2) > div:first-child p {
  margin: 0 !important;
  color: #555555 !important;
  font-size: 13px !important;
  font-weight: 400 !important;
  line-height: 36px !important;
  white-space: nowrap;
}
.permission-pagination nav > div:nth-child(2) > div:first-child p span {
  color: #0D2B5A !important;
  font-weight: 600 !important;
}
.permission-pagination {
  /*
  |--------------------------------------------------------------------------
  | Pagination Controls
  |--------------------------------------------------------------------------
  */
}
.permission-pagination nav > div:nth-child(2) > div:last-child {
  flex: 0 0 auto;
  margin: 0 !important;
}
.permission-pagination nav > div:nth-child(2) > div:last-child > span {
  display: inline-flex !important;
  align-items: center;
  gap: 0;
  margin: 0 !important;
  padding: 0 !important;
  border-radius: 7px;
  box-shadow: none !important;
}
.permission-pagination {
  /*
  |--------------------------------------------------------------------------
  | Pagination Items
  |--------------------------------------------------------------------------
  */
}
.permission-pagination nav a,
.permission-pagination nav span {
  min-width: 36px;
  height: 36px;
  margin: 0 !important;
  padding: 0 10px !important;
  border: 1px solid rgba(16, 26, 35, 0.08) !important;
  border-radius: 0;
  background: #fff !important;
  color: #555555 !important;
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  font-size: 13px !important;
  font-weight: 500 !important;
  line-height: 1 !important;
  text-decoration: none !important;
  box-sizing: border-box;
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
}
.permission-pagination {
  /*
  |--------------------------------------------------------------------------
  | First Pagination Item
  |--------------------------------------------------------------------------
  */
}
.permission-pagination nav > div:nth-child(2) > div:last-child > span > *:first-child {
  border-top-left-radius: 7px !important;
  border-bottom-left-radius: 7px !important;
}
.permission-pagination {
  /*
  |--------------------------------------------------------------------------
  | Last Pagination Item
  |--------------------------------------------------------------------------
  */
}
.permission-pagination nav > div:nth-child(2) > div:last-child > span > *:last-child {
  border-top-right-radius: 7px !important;
  border-bottom-right-radius: 7px !important;
}
.permission-pagination {
  /*
  |--------------------------------------------------------------------------
  | Pagination Links
  |--------------------------------------------------------------------------
  */
}
.permission-pagination nav a:hover {
  border-color: rgba(23, 114, 69, 0.22) !important;
  background: rgba(23, 114, 69, 0.055) !important;
  color: #177245 !important;
}
.permission-pagination nav a:focus {
  outline: none;
  border-color: rgba(23, 114, 69, 0.25) !important;
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.08) !important;
}
.permission-pagination {
  /*
  |--------------------------------------------------------------------------
  | Current Page
  |--------------------------------------------------------------------------
  */
}
.permission-pagination nav span[aria-current=page] {
  padding: 0 !important;
  border: 0 !important;
}
.permission-pagination nav span[aria-current=page] span {
  width: 100%;
  border-color: #177245 !important;
  background: #177245 !important;
  color: #fff !important;
  font-weight: 600 !important;
  cursor: default;
}
.permission-pagination {
  /*
  |--------------------------------------------------------------------------
  | Disabled Previous / Next
  |--------------------------------------------------------------------------
  */
}
.permission-pagination nav span[aria-disabled=true] {
  display: inline-flex !important;
  color: rgba(85, 85, 85, 0.22) !important;
  background: #fff !important;
  cursor: not-allowed;
}
.permission-pagination nav span[aria-disabled=true] > span {
  color: rgba(85, 85, 85, 0.22) !important;
  background: #f8f9fa !important;
  cursor: not-allowed;
}
.permission-pagination {
  /*
  |--------------------------------------------------------------------------
  | SVG Icons
  |--------------------------------------------------------------------------
  */
}
.permission-pagination nav svg {
  width: 16px !important;
  height: 16px !important;
  margin: 0 !important;
  display: block;
  flex-shrink: 0;
  color: currentColor;
}
.permission-pagination {
  /*
  |--------------------------------------------------------------------------
  | Previous / Next Buttons
  |--------------------------------------------------------------------------
  */
}
