  color: #dc4b4b;
  display: flex;
  align-items: center;
  justify-content: center;
}
.my-smart-buy-payment-result-icon i {
  font-size: 29px;
}

.my-smart-buy-payment-result-label {
  display: inline-block;
  margin-bottom: 7px;
  color: #dc4b4b;
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.my-smart-buy-payment-result-card h1 {
  max-width: 600px;
  margin: 0 auto 7px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 24px;
  font-weight: 700;
  line-height: 1.3;
}

.my-smart-buy-payment-result-description {
  max-width: 570px;
  margin: 0 auto 18px;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*==================================================
| Failed Notice
==================================================*/
.my-smart-buy-payment-failed-notice {
  margin-bottom: 13px;
  padding: 11px 12px;
  border: 1px solid rgba(220, 75, 75, 0.13);
  border-radius: 8px;
  background: #fff7f7;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  text-align: left;
}

.my-smart-buy-payment-failed-notice__icon {
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  border-radius: 7px;
  background: #fdeaea;
  color: #dc4b4b;
  display: flex;
  align-items: center;
  justify-content: center;
}
.my-smart-buy-payment-failed-notice__icon i {
  font-size: 16px;
}

.my-smart-buy-payment-failed-notice > div:last-child {
  min-width: 0;
}

.my-smart-buy-payment-failed-notice strong {
  display: block;
  margin-bottom: 2px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.my-smart-buy-payment-failed-notice p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.45;
}

/*==================================================
| Summary
==================================================*/
.my-smart-buy-payment-result-summary {
  margin-bottom: 12px;
  border: 1px solid rgba(16, 26, 35, 0.065);
  border-radius: 9px;
  background: #fafbfc;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  overflow: hidden;
}

.my-smart-buy-payment-result-summary > div {
  min-height: 68px;
  padding: 10px;
  border-right: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
}

.my-smart-buy-payment-result-summary > div:last-child {
  border-right: 0;
}

.my-smart-buy-payment-result-summary span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.my-smart-buy-payment-result-summary strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.my-smart-buy-payment-result-summary strong.is-failed {
  color: #dc4b4b;
}

/*==================================================
| Reference
==================================================*/
.my-smart-buy-payment-result-reference {
  min-height: 52px;
  margin-bottom: 15px;
  padding: 8px 10px;
  border: 1px solid rgba(16, 26, 35, 0.065);
  border-radius: 8px;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  text-align: left;
}

.my-smart-buy-payment-result-reference > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.my-smart-buy-payment-result-reference span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.my-smart-buy-payment-result-reference strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.my-smart-buy-payment-failed-code {
  padding: 5px 8px;
  border-radius: 6px;
  background: #fdeaea;
  color: #dc4b4b !important;
  font-size: 14px !important;
  font-weight: 600;
}

/*==================================================
| Actions
==================================================*/
.my-smart-buy-payment-result-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.my-smart-buy-payment-result-primary,
.my-smart-buy-payment-result-secondary {
  min-height: 40px;
  padding: 0 13px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s ease;
}

.my-smart-buy-payment-result-primary.is-failed {
  background: #dc4b4b;
  color: #fff;
}
.my-smart-buy-payment-result-primary.is-failed:hover {
  background: rgba(220, 75, 75, 0.8);
  color: #fff;
}

.my-smart-buy-payment-result-secondary {
  border: 1px solid rgba(16, 26, 35, 0.08);
  background: #fff;
  color: #555555;
}
.my-smart-buy-payment-result-secondary:hover {
  background: #f7f8f9;
  color: #0D2B5A;
}

/*==================================================
| Info Grid
==================================================*/
.my-smart-buy-payment-result-info-grid {
  max-width: 760px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 15px;
}

.my-smart-buy-payment-result-info-card {
  min-width: 0;
  padding: 14px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.025);
  display: flex;
  align-items: flex-start;
  gap: 9px;
}

.my-smart-buy-payment-result-info-card__icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.07);
  color: #177245;
  display: flex;
  align-items: center;
  justify-content: center;
}
.my-smart-buy-payment-result-info-card__icon i {
  font-size: 18px;
}

.my-smart-buy-payment-result-info-card > div:last-child {
  min-width: 0;
}

.my-smart-buy-payment-result-info-card span {
  display: block;
  margin-bottom: 2px;
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.my-smart-buy-payment-result-info-card strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.my-smart-buy-payment-result-info-card p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.45;
}

.my-smart-buy-payment-result-info-card a {
  margin-top: 7px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}

/*==================================================
| Failed Tips
==================================================*/
.my-smart-buy-payment-failed-tips {
  margin: 7px 0 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.my-smart-buy-payment-failed-tips li {
  position: relative;
  padding-left: 14px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

.my-smart-buy-payment-failed-tips li::before {
  content: "";
  position: absolute;
  top: 7px;
  left: 0;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #dc4b4b;
}

/*==================================================
| Responsive MD
==================================================*/
@media (min-width: 768px) and (max-width: 991px) {
  .my-smart-buy-payment-result-card {
    padding: 24px;
  }
  .my-smart-buy-payment-result-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .my-smart-buy-payment-result-summary > div {
    border-right: 0;
    border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  }
  .my-smart-buy-payment-result-summary > div:nth-child(odd) {
    border-right: 1px solid rgba(16, 26, 35, 0.055);
  }
  .my-smart-buy-payment-result-summary > div:nth-last-child(-n+2) {
    border-bottom: 0;
  }
}
/*==================================================
| Responsive XS
==================================================*/
@media (max-width: 767px) {
  .my-smart-buy-payment-result-card {
    padding: 18px 14px;
  }
  .my-smart-buy-payment-result-card h1 {
    font-size: 20px;
  }
  .my-smart-buy-payment-result-summary {
    grid-template-columns: 1fr;
  }
  .my-smart-buy-payment-result-summary > div,
  .my-smart-buy-payment-result-summary > div:nth-child(odd) {
    border-right: 0;
    border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  }
  .my-smart-buy-payment-result-summary > div:last-child {
    border-bottom: 0;
  }
  .my-smart-buy-payment-result-reference {
    align-items: flex-start;
    flex-direction: column;
  }
  .my-smart-buy-payment-failed-code {
    align-self: flex-end;
  }
  .my-smart-buy-payment-result-actions {
    align-items: stretch;
    flex-direction: column;
  }
  .my-smart-buy-payment-result-primary,
  .my-smart-buy-payment-result-secondary {
    width: 100%;
  }
  .my-smart-buy-payment-result-info-grid {
    grid-template-columns: 1fr;
  }
}
/*
|--------------------------------------------------------------------------
| Customer Shop
|--------------------------------------------------------------------------
*/
.customer-shop-page {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
}

/*
|--------------------------------------------------------------------------
| Hero
|--------------------------------------------------------------------------
*/
.customer-shop-hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  min-height: 190px;
  margin-bottom: 18px;
  padding: 30px 34px;
  overflow: hidden;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(23, 114, 69, 0.08), #ffffff 65%);
  border: 1px solid rgba(23, 114, 69, 0.12);
}

.customer-shop-hero__content {
  max-width: 620px;
}

.customer-shop-hero__eyebrow {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 9px;
  color: #177245;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.customer-shop-hero__eyebrow span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #177245;
}

.customer-shop-hero h1 {
  margin: 0 0 9px;
  color: #0D2B5A;
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
}
.customer-shop-hero h1 strong {
  color: #177245;
  font-weight: 700;
}

.customer-shop-hero p {
  max-width: 560px;
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.65;
}

/*
|--------------------------------------------------------------------------
| Hero Stats
|--------------------------------------------------------------------------
*/
.customer-shop-hero__stats {
  display: grid;
  grid-template-columns: repeat(3, auto);
  gap: 0;
}
.customer-shop-hero__stats > div {
  min-width: 105px;
  padding: 0 20px;
  border-left: 1px solid rgba(221, 221, 221, 0.8);
}
.customer-shop-hero__stats > div:first-child {
  border-left: 0;
}
.customer-shop-hero__stats strong {
  display: block;
  margin-bottom: 4px;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.3;
  font-weight: 700;
}
.customer-shop-hero__stats span {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

/*
|--------------------------------------------------------------------------
| Topbar
|--------------------------------------------------------------------------
*/
.customer-shop-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 20px;
}

.customer-shop-topbar__left {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #999;
  font-size: 14px;
}
.customer-shop-topbar__left strong {
  color: #0D2B5A;
  font-weight: 600;
}

.customer-shop-breadcrumb {
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}
.customer-shop-breadcrumb:hover {
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Cart
|--------------------------------------------------------------------------
*/
.customer-shop-cart {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #fff;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s;
}
.customer-shop-cart i {
  color: #177245;
  font-size: 17px;
}
.customer-shop-cart b {
  min-width: 20px;
  height: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #177245;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
}
.customer-shop-cart:hover {
  border-color: rgba(23, 114, 69, 0.4);
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Main Layout
|--------------------------------------------------------------------------
*/
.customer-shop-layout {
  display: grid;
  grid-template-columns: 245px minmax(0, 1fr);
  align-items: start;
  gap: 22px;
}

/*
|--------------------------------------------------------------------------
| Sidebar
|--------------------------------------------------------------------------
*/
.customer-shop-sidebar {
  position: sticky;
  top: 18px;
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 17px;
  border: 1px solid #ddd;
  border-radius: 12px;
  background: #fff;
}

.customer-shop-sidebar__mobile-header {
  display: none;
}

.customer-shop-sidebar__heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
  padding-bottom: 15px;
  border-bottom: 1px solid #ddd;
}
.customer-shop-sidebar__heading span {
  display: block;
  margin-bottom: 3px;
  color: #177245;
  font-size: 14px;
  font-weight: 600;
}
.customer-shop-sidebar__heading h2 {
  margin: 0;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.3;
  font-weight: 700;
}

.customer-shop-clear-btn {
  padding: 0;
  border: 0;
  background: transparent;
  color: #177245;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

/*
|--------------------------------------------------------------------------
| Filter
|--------------------------------------------------------------------------
*/
.customer-shop-filter {
  padding: 17px 0;
  border-bottom: 1px solid #ddd;
}
.customer-shop-filter:last-of-type {
  border-bottom: 0;
}

.customer-shop-filter__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}
.customer-shop-filter__header h3 {
  margin: 0;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 700;
}
.customer-shop-filter__header i {
  color: #999;
  font-size: 17px;
}

.customer-shop-filter__body {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/*
|--------------------------------------------------------------------------
| Checkbox
|--------------------------------------------------------------------------
*/
.customer-shop-check {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 22px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
  cursor: pointer;
}
.customer-shop-check input {
  position: absolute;
  width: 0;
  height: 0;
  opacity: 0;
}
.customer-shop-check__box {
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #c9c9c9;
  border-radius: 4px;
  background: #fff;
  transition: 0.2s;
}
input:checked + .customer-shop-check__box {
  border-color: #177245;
  background: #177245;
}
input:checked + .customer-shop-check__box::after {
  content: "";
  width: 7px;
  height: 4px;
  margin-top: -1px;
  border-left: 1.5px solid #fff;
  border-bottom: 1.5px solid #fff;
  transform: rotate(-45deg);
}
.customer-shop-check__label {
  flex: 1;
}
.customer-shop-check small {
  color: #999;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Rating
|--------------------------------------------------------------------------
*/
.customer-shop-rating-check {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 22px;
  cursor: pointer;
}
.customer-shop-rating-check input {
  position: absolute;
  width: 0;
  height: 0;
  opacity: 0;
}

.customer-shop-radio {
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  border: 1px solid #c9c9c9;
  border-radius: 50%;
  transition: 0.2s;
}

.customer-shop-rating-check input:checked + .customer-shop-radio {
  border: 4px solid #177245;
}

.customer-shop-stars {
  color: #e2a800;
  font-size: 14px;
  letter-spacing: 1px;
}

.customer-shop-rating-check small {
  color: #555555;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Price
|--------------------------------------------------------------------------
*/
.customer-shop-price-inputs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
}
.customer-shop-price-inputs > div {
  min-width: 0;
}
.customer-shop-price-inputs label {
  display: block;
  margin-bottom: 5px;
  color: #888;
  font-size: 14px;
}

.customer-shop-price-input {
  position: relative;
}
.customer-shop-price-input span {
  position: absolute;
  top: 50%;
  left: 9px;
  transform: translateY(-50%);
  color: #999;
  font-size: 14px;
}
.customer-shop-price-input input {
  width: 100%;
  height: 38px;
  padding: 0 8px 0 22px;
  border: 1px solid #ddd;
  border-radius: 7px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
}
.customer-shop-price-input input:focus {
  border-color: rgba(23, 114, 69, 0.5);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.05);
}

.customer-shop-filter-btn {
  width: 100%;
  height: 38px;
  margin-top: 10px;
  border: 1px solid #177245;
  border-radius: 7px;
  background: #177245;
  color: #fff;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s;
}
.customer-shop-filter-btn:hover {
  opacity: 0.92;
}

/*
|--------------------------------------------------------------------------
| Sidebar Clear
|--------------------------------------------------------------------------
*/
.customer-shop-sidebar__clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 38px;
  margin-top: 8px;
  border: 0;
  background: transparent;
  color: #888;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.customer-shop-sidebar__clear:hover {
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Product Area
|--------------------------------------------------------------------------
*/
.customer-shop-products {
  min-width: 0;
}

/*
|--------------------------------------------------------------------------
| Toolbar
|--------------------------------------------------------------------------
*/
.customer-shop-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  min-height: 42px;
  margin-bottom: 12px;
}

.customer-shop-toolbar__result {
  display: flex;
  align-items: baseline;
  gap: 5px;
}
.customer-shop-toolbar__result strong {
  color: #0D2B5A;
  font-size: 16px;
  font-weight: 700;
}
.customer-shop-toolbar__result span {
  color: #555555;
  font-size: 14px;
}

.customer-shop-toolbar__right {
  display: flex;
  align-items: center;
  gap: 8px;
}

/*
|--------------------------------------------------------------------------
| Search
|--------------------------------------------------------------------------
*/
.customer-shop-search {
  position: relative;
  width: 235px;
}
.customer-shop-search i {
  position: absolute;
  top: 50%;
  left: 11px;
  transform: translateY(-50%);
  color: #999;
  font-size: 17px;
  pointer-events: none;
}
.customer-shop-search input {
  width: 100%;
  height: 40px;
  padding: 0 10px 0 35px;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
}
.customer-shop-search input::placeholder {
  color: #999;
}
.customer-shop-search input:focus {
  border-color: rgba(23, 114, 69, 0.5);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.05);
}

/*
|--------------------------------------------------------------------------
| Sort
|--------------------------------------------------------------------------
*/
.customer-shop-sort-wrap {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 40px;
  padding: 0 9px;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #fff;
}
.customer-shop-sort-wrap > span {
  color: #999;
  font-size: 14px;
}

.customer-shop-sort {
  height: 34px;
  padding: 0 4px;
  border: 0;
  outline: 0;
  background: transparent;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

/*
|--------------------------------------------------------------------------
| View Switcher
|--------------------------------------------------------------------------
*/
.customer-shop-view {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 40px;
  padding: 3px;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #fff;
}
.customer-shop-view button {
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: #999;
  cursor: pointer;
}
.customer-shop-view button.active {
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Active Filters
|--------------------------------------------------------------------------
*/
.customer-shop-active-filters {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 16px;
}
.customer-shop-active-filters > span {
  margin-right: 3px;
  color: #888;
  font-size: 14px;
}
.customer-shop-active-filters button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: 28px;
  padding: 0 8px;
  border: 1px solid rgba(23, 114, 69, 0.16);
  border-radius: 5px;
  background: rgba(23, 114, 69, 0.05);
  color: #177245;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  cursor: pointer;
}
.customer-shop-active-filters button i {
  font-size: 14px;
}
.customer-shop-active-filters .customer-shop-active-filters__clear {
  border-color: transparent;
  background: transparent;
  color: #888;
}

/*
|--------------------------------------------------------------------------
| Product Grid
|--------------------------------------------------------------------------
*/
.customer-shop-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 15px;
}

/*
|--------------------------------------------------------------------------
| Product Card
|--------------------------------------------------------------------------
*/
.customer-product-card {
  min-width: 0;
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 10px;
  background: #fff;
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}
.customer-product-card:hover {
  border-color: rgba(23, 114, 69, 0.25);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.06);
  transform: translateY(-3px);
}

/*
|--------------------------------------------------------------------------
| Product Image
|--------------------------------------------------------------------------
*/
.customer-product-card__image {
  position: relative;
  aspect-ratio: 1/1.12;
  overflow: hidden;
  background: #f5f5f5;
}
.customer-product-card__image > a {
  display: block;
  width: 100%;
  height: 100%;
}
.customer-product-card__image img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transition: transform 0.45s ease;
}
.customer-product-card__image:hover img {
  transform: scale(1.045);
}

/*
|--------------------------------------------------------------------------
| Product Badges
|--------------------------------------------------------------------------
*/
.customer-product-card__badges {
  position: absolute;
  top: 10px;
  left: 10px;
  display: flex;
  gap: 5px;
}
.customer-product-card__badges span {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  padding: 0 7px;
  border-radius: 5px;
  color: #fff;
  font-size: 14px;
  line-height: 1;
  font-weight: 700;
}
.customer-product-card__badges span.sale {
  background: #177245;
}
.customer-product-card__badges span.new {
  background: #0D2B5A;
}

/*
|--------------------------------------------------------------------------
| Wishlist
|--------------------------------------------------------------------------
*/
.customer-product-card__wishlist {
  position: absolute;
  top: 9px;
  right: 9px;
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, 0.7);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.95);
  color: #0D2B5A;
  font-size: 17px;
  cursor: pointer;
  transition: 0.2s;
}
.customer-product-card__wishlist:hover {
  color: #177245;
  transform: scale(1.05);
}

/*
|--------------------------------------------------------------------------
| Quick View
|--------------------------------------------------------------------------
*/
.customer-product-card__quick {
  position: absolute;
  right: 10px;
  bottom: 10px;
  left: 10px;
  height: 34px;
  border: 0;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.94);
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  opacity: 0;
  transform: translateY(6px);
  transition: 0.25s;
}

.customer-product-card__image:hover .customer-product-card__quick {
  opacity: 1;
  transform: translateY(0);
}

/*
|--------------------------------------------------------------------------
| Product Content
|--------------------------------------------------------------------------
*/
.customer-product-card__content {
  padding: 13px;
}

.customer-product-card__category {
  display: block;
  margin-bottom: 4px;
  color: #177245;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;
}

.customer-product-card__content h2 {
  min-height: 40px;
  margin: 0 0 7px;
}
.customer-product-card__content h2 a {
  display: -webkit-box;
  overflow: hidden;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.45;
  font-weight: 650;
  text-decoration: none;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.customer-product-card__content h2 a:hover {
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Rating
|--------------------------------------------------------------------------
*/
.customer-product-card__rating {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 10px;
}
.customer-product-card__rating > span {
  color: #e2a800;
  font-size: 14px;
  letter-spacing: 1px;
}
.customer-product-card__rating small {
  color: #888;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Product Bottom
|--------------------------------------------------------------------------
*/
.customer-product-card__bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.customer-product-card__price {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 5px;
}
.customer-product-card__price del {
  color: #aaa;
  font-size: 14px;
}
.customer-product-card__price strong {
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.3;
  font-weight: 700;
}

/*
|--------------------------------------------------------------------------
| Add To Cart
|--------------------------------------------------------------------------
*/
.customer-product-card__cart {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(23, 114, 69, 0.2);
  border-radius: 7px;
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
  font-size: 17px;
  cursor: pointer;
  transition: 0.2s;
}
.customer-product-card__cart:hover {
  border-color: #177245;
  background: #177245;
  color: #fff;
  transform: translateY(-1px);
}

/*
|--------------------------------------------------------------------------
| Pagination
|--------------------------------------------------------------------------
*/
.customer-shop-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 28px;
}
.customer-shop-pagination button {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s;
}
.customer-shop-pagination button:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}
.customer-shop-pagination button.active {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.customer-shop-pagination button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.customer-shop-pagination > span {
  padding: 0 3px;
  color: #999;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| XL
|--------------------------------------------------------------------------
*/
@media (min-width: 1200px) and (max-width: 1399px) {
  .customer-shop-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
/*
|--------------------------------------------------------------------------
| LG
|--------------------------------------------------------------------------
*/
@media (min-width: 992px) and (max-width: 1199px) {
  .customer-shop-layout {
    grid-template-columns: 220px minmax(0, 1fr);
  }
  .customer-shop-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .customer-shop-hero__stats {
    display: none;
  }
  .customer-shop-search {
    width: 190px;
  }
}
/*
|--------------------------------------------------------------------------
| MD
|--------------------------------------------------------------------------
*/
@media (min-width: 768px) and (max-width: 991px) {
  .customer-shop-hero {
    min-height: auto;
    padding: 25px;
  }
  .customer-shop-layout {
    grid-template-columns: 1fr;
  }
  .customer-shop-sidebar {
    position: static;
  }
  .customer-shop-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .customer-shop-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }
  .customer-shop-toolbar__right {
    width: 100%;
  }
  .customer-shop-search {
    flex: 1;
    width: auto;
  }
}
/*
|--------------------------------------------------------------------------
| XS
|--------------------------------------------------------------------------
*/
@media (max-width: 767px) {
  .customer-shop-hero {
    padding: 20px;
  }
  .customer-shop-hero h1 {
    font-size: 24px;
  }
  .customer-shop-topbar {
    margin-bottom: 15px;
  }
  .customer-shop-layout {
    gap: 15px;
  }
  .customer-shop-sidebar {
    padding: 14px;
  }
  .customer-shop-toolbar__right {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 7px;
  }
  .customer-shop-search {
    grid-column: 1/-1;
    width: 100%;
  }
  .customer-shop-sort-wrap {
    width: 100%;
  }
  .customer-shop-view {
    width: 100%;
    justify-content: center;
  }
  .customer-shop-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 9px;
  }
  .customer-product-card__content {
    padding: 10px;
  }
  .customer-product-card__category {
    font-size: 14px;
  }
  .customer-product-card__content h2 {
    min-height: 38px;
  }
  .customer-product-card__price {
    display: block;
  }
  .customer-product-card__price del,
  .customer-product-card__price strong {
    display: block;
  }
  .customer-product-card__cart {
    width: 32px;
    height: 32px;
    flex-basis: 32px;
    font-size: 16px;
  }
  .customer-product-card__quick {
    display: none;
  }
}
/*
|--------------------------------------------------------------------------
| CUSTOMER PRODUCT DETAILS
|--------------------------------------------------------------------------
*/
.customer-product-details {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
  color: #555555;
  font-size: 14px;
  /*
  |--------------------------------------------------------------------------
  | BREADCRUMB
  |--------------------------------------------------------------------------
  */
}
