  font-weight: 700 !important;
}
.customer-product-details {
  /*
  |--------------------------------------------------------------------------
  | PRODUCT RATING
  |--------------------------------------------------------------------------
  */
}
.customer-product-details .customer-product-info__rating {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
