  letter-spacing: 1px;
}
.customer-product-details .customer-product-info__separator {
  color: #ccc !important;
  font-size: 14px;
}
.customer-product-details {
  /*
  |--------------------------------------------------------------------------
  | PRICE
  |--------------------------------------------------------------------------
  */
}
.customer-product-details .customer-product-info__price {
