  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}
.customer-product-details .customer-product-option__values label {
  position: relative;
  display: inline-flex;
  cursor: pointer;
}
.customer-product-details .customer-product-option__values label input {
  position: absolute;
  width: 0;
  height: 0;
  opacity: 0;
}
.customer-product-details .customer-product-option__values label > span {
  min-width: 44px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 12px;
  border: 1px solid #d5d5d5;
  border-radius: 7px;
  background: #fff;
