  |--------------------------------------------------------------------------
  */
}
.product-create-page__switch-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  cursor: pointer;
}
.product-create-page__switch-row > input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.product-create-page__switch-row > input:checked + .product-create-page__switch {
  background: #177245;
}
.product-create-page__switch-row > input:checked + .product-create-page__switch::after {
  transform: translateX(18px);
}
.product-create-page__switch-text {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.product-create-page__switch-text strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
}
.product-create-page__switch-text small {
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.product-create-page__switch {
  position: relative;
  flex: 0 0 40px;
  width: 40px;
  height: 22px;
  border-radius: 20px;
  background: #eaecf0;
  -webkit-transition: all 0.3s linear 0s;
  -o-transition: all 0.3s linear 0s;
  transition: all 0.3s linear 0s;
}
.product-create-page__switch::after {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  content: "";
  -webkit-transition: all 0.3s linear 0s;
  -o-transition: all 0.3s linear 0s;
  transition: all 0.3s linear 0s;
}
.product-create-page__check-item {
