  font-size: 18px;
}
.product-create-page__actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.product-create-page__cancel-button, .product-create-page__submit-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 6px;
