  font-size: 14px;
  font-weight: 500;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  -webkit-transition: all 0.3s linear 0s;
  -o-transition: all 0.3s linear 0s;
  transition: all 0.3s linear 0s;
}
.product-create-page__cancel-button {
  border: 1px solid #eaecf0;
  background: #fff;
  color: #555555;
}
.product-create-page__cancel-button:hover {
  border-color: #177245;
  color: #177245;
}
.product-create-page__submit-button {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.product-create-page__submit-button i {
  font-size: 18px;
}
.product-create-page__submit-button:hover {
  border-color: #D4AF37;
  background: #D4AF37;
}
.product-create-page {
  /*
  |--------------------------------------------------------------------------
  | Responsive
  |--------------------------------------------------------------------------
  */
}
@media (min-width: 1200px) and (max-width: 1399px) {
  .product-create-page__layout {
    grid-template-columns: minmax(0, 1fr) 280px;
  }
  .product-create-page__grid--three {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .product-create-page__gallery-preview {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (min-width: 992px) and (max-width: 1199px) {
  .product-create-page__layout {
    grid-template-columns: 1fr;
  }
  .product-create-page__sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: start;
  }
  .product-create-page__actions {
    grid-column: 1/-1;
    flex-direction: row;
  }
  .product-create-page__cancel-button, .product-create-page__submit-button {
    flex: 1;
    width: auto;
  }
}
@media (min-width: 768px) and (max-width: 991px) {
  .product-create-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .product-create-page__back-button {
    width: 100%;
  }
  .product-create-page__grid, .product-create-page__grid--three {
    grid-template-columns: 1fr;
  }
  .product-create-page__sidebar {
    grid-template-columns: 1fr;
  }
  .product-create-page__actions {
    grid-column: auto;
    flex-direction: column;
  }
  .product-create-page__cancel-button, .product-create-page__submit-button {
    width: 100%;
  }
  .product-create-page__variant-generator {
    align-items: flex-start;
    flex-direction: column;
  }
  .product-create-page__generate-button {
    width: 100%;
  }
  .product-create-page__media-heading {
    flex-direction: column;
  }
  .product-create-page__gallery-preview {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (min-width: 480px) and (max-width: 767px) {
  .product-create-page__title {
    font-size: 22px;
  }
  .product-create-page__card-header, .product-create-page__card-body {
    padding: 16px;
  }
