    width: 36px;
    height: 36px;
  }
  .product-create-page__card-header h2 {
    font-size: 16px;
  }
  .product-create-page__gallery-preview {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .product-create-page__thumbnail-preview {
    min-height: 220px;
  }
  .product-create-page__thumbnail-preview > img {
    min-height: 220px;
  }
}
@media (max-width: 767px) {
  .product-create-page__header {
    gap: 16px;
    margin-bottom: 18px;
  }
  .product-create-page__title {
    font-size: 20px;
  }
  .product-create-page__subtitle {
    line-height: 1.5;
  }
  .product-create-page__card {
    border-radius: 6px;
  }
  .product-create-page__card-body {
    gap: 16px;
  }
  .product-create-page__rich-toolbar {
    gap: 2px;
  }
  .product-create-page__rich-toolbar button {
    width: 32px;
    height: 32px;
  }
  .product-create-page__gallery-preview {
    gap: 8px;
  }
  .product-create-page__variant-generator {
    padding: 14px;
  }
  .product-create-page__generator-content {
    align-items: flex-start;
  }
  .product-create-page__values-grid {
    gap: 6px;
  }
}

