    font-size: 22px;
  }
  .product-details-page__header-actions {
    flex-direction: column;
  }
  .product-details-page__button {
    width: 100%;
  }
  .product-details-page__card {
    padding: 16px;
  }
  .product-details-page__field-grid {
    grid-template-columns: 1fr;
  }
  .product-details-page__pricing-grid {
    grid-template-columns: 1fr;
  }
  .product-details-page__gallery {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .product-details-page__variant-top {
    align-items: flex-start;
    flex-direction: column;
  }
  .product-details-page__lightbox {
    padding: 15px;
  }
}
@media (max-width: 767px) {
  .product-details-page__meta {
