  background: rgba(255, 193, 7, 0.12);
  color: #947000;
}
.inventory-stat-card__icon--danger {
  background: rgba(220, 53, 69, 0.1);
  color: #dc3545;
}
.inventory-stat-card span {
  display: block;
  margin-bottom: 4px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}
.inventory-stat-card strong {
  display: block;
  color: #0D2B5A;
  font-size: 24px;
  line-height: 1.2;
  font-weight: 700;
}

/*
|--------------------------------------------------------------------------
| Inventory Card
|--------------------------------------------------------------------------
*/
.inventory-card {
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 12px;
  background: #fff;
}

/*
|--------------------------------------------------------------------------
| Toolbar
|--------------------------------------------------------------------------
*/
.inventory-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 17px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.inventory-toolbar__actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/*
|--------------------------------------------------------------------------
| Search
|--------------------------------------------------------------------------
*/
.inventory-search {
  position: relative;
  width: 100%;
  max-width: 300px;
}
.inventory-search i {
  position: absolute;
  top: 50%;
  left: 12px;
  transform: translateY(-50%);
  color: #888;
  font-size: 17px;
  pointer-events: none;
}
.inventory-search input {
  width: 100%;
  height: 42px;
  padding: 0 12px 0 38px;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  transition: 0.2s;
}
.inventory-search input::placeholder {
  color: #999;
}
.inventory-search input:focus {
  border-color: rgba(23, 114, 69, 0.5);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.06);
}

/*
|--------------------------------------------------------------------------
| Filters
|--------------------------------------------------------------------------
*/
.inventory-filter {
  height: 42px;
  min-width: 135px;
  padding: 0 12px;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  cursor: pointer;
}
.inventory-filter:focus {
  border-color: rgba(23, 114, 69, 0.5);
}

.inventory-filter-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 42px;
  padding: 0 12px;
  border: 1px solid rgba(255, 193, 7, 0.3);
  border-radius: 8px;
  background: rgba(255, 193, 7, 0.05);
  color: #947000;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  transition: 0.2s;
}
.inventory-filter-link i {
  font-size: 16px;
}
.inventory-filter-link:hover {
  border-color: #ffc107;
  color: #947000;
}
.inventory-filter-link--danger {
  border-color: rgba(220, 53, 69, 0.25);
  background: rgba(220, 53, 69, 0.05);
  color: #dc3545;
}
.inventory-filter-link--danger:hover {
  border-color: #dc3545;
  color: #dc3545;
}

/*
|--------------------------------------------------------------------------
| Table Wrapper
|--------------------------------------------------------------------------
*/
.inventory-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

/*
|--------------------------------------------------------------------------
| Table
|--------------------------------------------------------------------------
*/
.inventory-table {
  width: 100%;
  min-width: 1050px;
  border-collapse: collapse;
}
.inventory-table th,
.inventory-table td {
  padding: 14px 16px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.65);
  text-align: left;
  vertical-align: middle;
  font-size: 14px;
  line-height: 1.5;
}
.inventory-table th {
  background: #F2F4F7;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}
.inventory-table td {
  color: #555555;
}
.inventory-table tbody tr {
  transition: 0.2s;
}
.inventory-table tbody tr:hover {
  background: rgba(23, 114, 69, 0.02);
}
.inventory-table tbody tr:last-child td {
  border-bottom: 0;
}

/*
|--------------------------------------------------------------------------
| Product
|--------------------------------------------------------------------------
*/
.inventory-product {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 230px;
}
.inventory-product__image {
  overflow: hidden;
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #f7f7f7;
}
.inventory-product__image img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.inventory-product__content {
  min-width: 0;
}
.inventory-product__content strong {
  display: block;
  margin-bottom: 3px;
  overflow: hidden;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.inventory-product__content span {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

/*
|--------------------------------------------------------------------------
| SKU
|--------------------------------------------------------------------------
*/
.inventory-sku {
  color: #555555;
  font-family: monospace;
  font-size: 14px;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Type
|--------------------------------------------------------------------------
*/
.inventory-type {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 27px;
  padding: 4px 9px;
  border-radius: 20px;
  background: rgba(23, 114, 69, 0.07);
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Price
|--------------------------------------------------------------------------
*/
.inventory-price {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Stock Input
|--------------------------------------------------------------------------
*/
.inventory-stock-input {
  display: flex;
  align-items: center;
  width: 145px;
  height: 38px;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  overflow: hidden;
}
.inventory-stock-input input {
  width: 75px;
  height: 100%;
  padding: 0 9px;
  border: 0;
  outline: none;
  background: transparent;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
}
.inventory-stock-input input:focus {
  box-shadow: inset 0 0 0 1px #177245;
}
.inventory-stock-input span {
  padding-right: 9px;
  color: #888;
  font-size: 14px;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Status
|--------------------------------------------------------------------------
*/
.inventory-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 27px;
  padding: 4px 9px;
  border-radius: 20px;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;
  white-space: nowrap;
}
.inventory-status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.inventory-status--in-stock {
  background: rgba(25, 135, 84, 0.1);
  color: #198754;
}
.inventory-status--low-stock {
  background: rgba(255, 193, 7, 0.12);
  color: #947000;
}
.inventory-status--out-of-stock {
  background: rgba(220, 53, 69, 0.1);
  color: #dc3545;
}

/*
|--------------------------------------------------------------------------
| Update Button
|--------------------------------------------------------------------------
*/
.inventory-update-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 37px;
  padding: 0 11px;
  border: 1px solid rgba(23, 114, 69, 0.3);
  border-radius: 7px;
  background: rgba(23, 114, 69, 0.05);
  color: #177245;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: 0.2s;
}
.inventory-update-btn i {
  font-size: 16px;
}
.inventory-update-btn:hover {
  border-color: #177245;
  background: #177245;
  color: #fff;
}

/*
|--------------------------------------------------------------------------
| Pagination
|--------------------------------------------------------------------------
*/
.inventory-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 15px 18px;
  border-top: 1px solid rgba(221, 221, 221, 0.65);
}
.inventory-pagination__info {
  color: #555555;
  font-size: 14px;
}
.inventory-pagination__info strong {
  color: #0D2B5A;
  font-weight: 600;
}
.inventory-pagination__buttons {
  display: flex;
  align-items: center;
  gap: 5px;
}
.inventory-pagination__buttons button {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  cursor: pointer;
  transition: 0.2s;
}
.inventory-pagination__buttons button:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}
.inventory-pagination__buttons button.active {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.inventory-pagination__buttons button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/*
|--------------------------------------------------------------------------
| Responsive - XL
|--------------------------------------------------------------------------
*/
@media (min-width: 1200px) and (max-width: 1399px) {
  .inventory-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .inventory-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }
  .inventory-search {
    max-width: 100%;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive - MD
|--------------------------------------------------------------------------
*/
@media (min-width: 768px) and (max-width: 991px) {
  .inventory-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .inventory-toolbar__actions {
    width: 100%;
  }
  .inventory-filter {
    flex: 1;
    min-width: 130px;
  }
  .inventory-filter-link {
    flex: 1;
  }
  .inventory-pagination {
    align-items: flex-start;
    flex-direction: column;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive - XS
|--------------------------------------------------------------------------
*/
@media (max-width: 767px) {
  .inventory-page__header h1 {
    font-size: 24px;
  }
  .inventory-stats {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .inventory-stat-card {
    padding: 15px;
  }
  .inventory-toolbar {
    padding: 14px;
  }
  .inventory-toolbar__actions {
    display: grid;
    grid-template-columns: 1fr;
    width: 100%;
  }
  .inventory-filter,
  .inventory-filter-link {
    width: 100%;
  }
  .inventory-pagination {
    padding: 14px;
  }
  .inventory-pagination__buttons {
    width: 100%;
    justify-content: center;
  }
}
