  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 20px;
}
.orders-stat-card__icon--warning {
  background: rgba(255, 193, 7, 0.12);
  color: #947000;
}
.orders-stat-card__icon--info {
  background: rgba(13, 202, 240, 0.1);
  color: #087f99;
}
.orders-stat-card__icon--success {
  background: rgba(25, 135, 84, 0.1);
  color: #198754;
}
.orders-stat-card span {
  display: block;
  margin-bottom: 4px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}
.orders-stat-card strong {
  display: block;
  color: #0D2B5A;
  font-size: 24px;
  line-height: 1.2;
  font-weight: 700;
}

/*
|--------------------------------------------------------------------------
| Orders Card
|--------------------------------------------------------------------------
*/
.orders-card {
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 12px;
  background: #fff;
}

/*
|--------------------------------------------------------------------------
| Toolbar
|--------------------------------------------------------------------------
*/
.orders-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 17px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.orders-toolbar__filters {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/*
|--------------------------------------------------------------------------
| Search
|--------------------------------------------------------------------------
*/
.orders-search {
  position: relative;
  width: 100%;
  max-width: 340px;
}
.orders-search i {
  position: absolute;
  top: 50%;
  left: 12px;
  transform: translateY(-50%);
  color: #888;
  font-size: 17px;
  pointer-events: none;
}
.orders-search input {
  width: 100%;
  height: 42px;
  padding: 0 12px 0 38px;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  transition: 0.2s;
}
.orders-search input::placeholder {
  color: #999;
}
.orders-search input:focus {
  border-color: rgba(23, 114, 69, 0.5);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.06);
}

/*
|--------------------------------------------------------------------------
| Filters
|--------------------------------------------------------------------------
*/
.orders-filter {
  height: 42px;
  min-width: 145px;
  padding: 0 12px;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  cursor: pointer;
}
.orders-filter:focus {
  border-color: rgba(23, 114, 69, 0.5);
}

/*
|--------------------------------------------------------------------------
| Table Wrapper
|--------------------------------------------------------------------------
*/
.orders-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

/*
|--------------------------------------------------------------------------
| Table
|--------------------------------------------------------------------------
*/
.orders-table {
  width: 100%;
  min-width: 1100px;
  border-collapse: collapse;
}
.orders-table th,
.orders-table td {
  padding: 14px 16px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.65);
  text-align: left;
  vertical-align: middle;
  font-size: 14px;
  line-height: 1.5;
}
.orders-table th {
  background: #F2F4F7;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}
.orders-table td {
  color: #555555;
}
.orders-table tbody tr {
  transition: 0.2s;
}
.orders-table tbody tr:hover {
  background: rgba(23, 114, 69, 0.02);
}
.orders-table tbody tr:last-child td {
  border-bottom: 0;
}

/*
|--------------------------------------------------------------------------
| Order Number
|--------------------------------------------------------------------------
*/
.orders-number {
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
}
.orders-number:hover {
  text-decoration: underline;
}

/*
|--------------------------------------------------------------------------
| Customer
|--------------------------------------------------------------------------
*/
.orders-customer {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 190px;
}
.orders-customer__avatar {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 14px;
  font-weight: 700;
}
.orders-customer strong {
  display: block;
  margin-bottom: 2px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  white-space: nowrap;
}
.orders-customer span {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Products
|--------------------------------------------------------------------------
*/
.orders-products {
  color: #555555;
  font-size: 14px;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Total
|--------------------------------------------------------------------------
*/
.orders-total {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Payment Status
|--------------------------------------------------------------------------
*/
.orders-payment {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 27px;
  padding: 4px 9px;
  border-radius: 20px;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;
  white-space: nowrap;
}
.orders-payment i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.orders-payment--paid {
  background: rgba(25, 135, 84, 0.1);
  color: #198754;
}
.orders-payment--pending {
  background: rgba(255, 193, 7, 0.12);
  color: #947000;
}
.orders-payment--failed {
  background: rgba(220, 53, 69, 0.1);
  color: #dc3545;
}

/*
|--------------------------------------------------------------------------
| Order Status
|--------------------------------------------------------------------------
*/
.orders-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 27px;
  padding: 4px 9px;
  border-radius: 20px;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;
  white-space: nowrap;
}
.orders-status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.orders-status--pending {
  background: rgba(255, 193, 7, 0.12);
  color: #947000;
}
.orders-status--processing {
  background: rgba(13, 202, 240, 0.1);
  color: #087f99;
}
.orders-status--shipped {
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
}
.orders-status--delivered, .orders-status--completed {
  background: rgba(25, 135, 84, 0.1);
  color: #198754;
}
.orders-status--cancelled {
  background: rgba(220, 53, 69, 0.1);
  color: #dc3545;
}

/*
|--------------------------------------------------------------------------
| Date
|--------------------------------------------------------------------------
*/
.orders-date {
  color: #555555;
  font-size: 14px;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| View Button
|--------------------------------------------------------------------------
*/
.orders-view-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 36px;
  padding: 0 11px;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  transition: 0.2s;
}
.orders-view-btn i {
  font-size: 16px;
}
.orders-view-btn:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Pagination
|--------------------------------------------------------------------------
*/
.orders-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 15px 18px;
  border-top: 1px solid rgba(221, 221, 221, 0.65);
}
.orders-pagination__info {
  color: #555555;
  font-size: 14px;
}
.orders-pagination__info strong {
  color: #0D2B5A;
  font-weight: 600;
}
.orders-pagination__buttons {
  display: flex;
  align-items: center;
  gap: 5px;
}
.orders-pagination__buttons button {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  cursor: pointer;
  transition: 0.2s;
}
.orders-pagination__buttons button:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}
.orders-pagination__buttons button.active {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.orders-pagination__buttons button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/*
|--------------------------------------------------------------------------
| Responsive - XL
|--------------------------------------------------------------------------
*/
@media (min-width: 1200px) and (max-width: 1399px) {
  .orders-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .orders-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }
  .orders-search {
    max-width: 100%;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive - MD
|--------------------------------------------------------------------------
*/
@media (min-width: 768px) and (max-width: 991px) {
  .orders-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .orders-page__header-actions {
    width: 100%;
  }
  .orders-export-btn {
    width: 100%;
  }
  .orders-toolbar__filters {
    width: 100%;
  }
  .orders-filter {
    flex: 1;
    min-width: 130px;
  }
  .orders-pagination {
    align-items: flex-start;
    flex-direction: column;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive - XS
|--------------------------------------------------------------------------
*/
@media (max-width: 767px) {
  .orders-stats {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .orders-stat-card {
    padding: 15px;
  }
  .orders-page__header h1 {
    font-size: 24px;
  }
  .orders-toolbar {
    padding: 14px;
  }
  .orders-toolbar__filters {
    display: grid;
    grid-template-columns: 1fr;
    width: 100%;
  }
  .orders-filter {
    width: 100%;
  }
  .orders-pagination {
    padding: 14px;
  }
  .orders-pagination__buttons {
    width: 100%;
    justify-content: center;
  }
}
/*
|--------------------------------------------------------------------------
| Order Details Page
|--------------------------------------------------------------------------
*/
.order-details-page {
  width: 100%;
  /*
  |--------------------------------------------------------------------------
  | Header
  |--------------------------------------------------------------------------
  */
}
.order-details-page__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 25px;
  margin-bottom: 22px;
}
.order-details-page__eyebrow {
  display: block;
  margin-bottom: 5px;
  color: #177245;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

/*
|--------------------------------------------------------------------------
| Back
|--------------------------------------------------------------------------
*/
.order-details-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 15px;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s;
}
.order-details-back i {
  font-size: 17px;
}
.order-details-back:hover {
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Title
|--------------------------------------------------------------------------
*/
.order-details-title {
  display: flex;
  align-items: center;
  gap: 15px;
}
.order-details-title h1 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
}
.order-details-title p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*
|--------------------------------------------------------------------------
| Main Status
|--------------------------------------------------------------------------
*/
.order-details-main-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 30px;
  padding: 5px 11px;
  border-radius: 20px;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;
  white-space: nowrap;
}
.order-details-main-status i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}
.order-details-main-status--processing {
  background: rgba(13, 202, 240, 0.1);
  color: #087f99;
}

/*
|--------------------------------------------------------------------------
| Header Actions
|--------------------------------------------------------------------------
*/
.order-details-page__actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.order-details-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 42px;
  padding: 0 14px;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s;
}
.order-details-action-btn i {
  font-size: 17px;
}
.order-details-action-btn:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}
.order-details-action-btn--primary {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.order-details-action-btn--primary:hover {
  border-color: #177245;
  background: #177245;
  color: #fff;
}

/*
|--------------------------------------------------------------------------
| Summary
|--------------------------------------------------------------------------
*/
.order-details-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 20px;
  border: 1px solid #ddd;
  border-radius: 11px;
  background: #fff;
}

.order-details-summary__item {
  padding: 17px 18px;
  border-right: 1px solid rgba(221, 221, 221, 0.7);
}
.order-details-summary__item:last-child {
  border-right: 0;
}
.order-details-summary__item span {
  display: block;
  margin-bottom: 5px;
  color: #555555;
  font-size: 14px;
}
.order-details-summary__item strong {
  display: block;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.3;
  font-weight: 700;
}

.order-details-summary__paid {
  color: #198754 !important;
}

/*
|--------------------------------------------------------------------------
| Main Grid
|--------------------------------------------------------------------------
*/
.order-details-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  align-items: start;
  gap: 20px;
}

.order-details-main,
.order-details-sidebar {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/*
|--------------------------------------------------------------------------
| Card
|--------------------------------------------------------------------------
*/
.order-details-card {
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 11px;
  background: #fff;
}
.order-details-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 16px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.order-details-card__header h2 {
  margin: 0;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 700;
}
.order-details-card__header span {
  display: block;
  margin-top: 3px;
  color: #555555;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Order Items
|--------------------------------------------------------------------------
*/
.order-items-table-wrapper {
  overflow-x: auto;
}

.order-items-table {
  width: 100%;
  min-width: 650px;
  border-collapse: collapse;
}
.order-items-table th,
.order-items-table td {
  padding: 14px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.65);
  text-align: left;
  vertical-align: middle;
  font-size: 14px;
}
.order-items-table th {
  background: #F2F4F7;
  color: #555555;
  font-weight: 600;
  white-space: nowrap;
}
.order-items-table td {
  color: #555555;
}
.order-items-table tbody tr:last-child td {
  border-bottom: 0;
}

/*
|--------------------------------------------------------------------------
| Product
|--------------------------------------------------------------------------
*/
.order-product {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 270px;
}
.order-product__image {
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #f7f7f7;
}
.order-product__image img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.order-product__content {
  min-width: 0;
}
.order-product__content strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.order-product__content span {
  display: block;
  margin-bottom: 2px;
  color: #555555;
  font-size: 14px;
}
.order-product__content small {
  display: block;
  color: #888;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Quantity
|--------------------------------------------------------------------------
*/
.order-item-quantity {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid #ddd;
  border-radius: 6px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

/*
|--------------------------------------------------------------------------
| Order Totals
|--------------------------------------------------------------------------
*/
.order-total-list {
  padding: 5px 18px;
}

.order-total-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 13px 0;
  border-bottom: 1px solid rgba(221, 221, 221, 0.6);
}
.order-total-row:last-child {
  border-bottom: 0;
}
.order-total-row span {
  color: #555555;
  font-size: 14px;
}
.order-total-row strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.order-total-row--grand {
  padding-top: 17px;
}
.order-total-row--grand span {
  color: #0D2B5A;
  font-weight: 700;
}
.order-total-row--grand strong {
  color: #177245;
  font-size: 20px;
}

/*
|--------------------------------------------------------------------------
| Shipment
|--------------------------------------------------------------------------
*/
.order-shipment-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 27px;
  padding: 4px 9px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 600;
}
.order-shipment-status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.order-shipment-status--pending {
  background: rgba(255, 193, 7, 0.12);
  color: #947000;
}

.order-shipment-box {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
  padding: 17px 18px;
}

.order-shipment-info {
  padding-right: 15px;
  border-right: 1px solid rgba(221, 221, 221, 0.7);
}
.order-shipment-info:last-child {
  padding-right: 0;
  padding-left: 15px;
  border-right: 0;
}
.order-shipment-info:not(:first-child) {
  padding-left: 15px;
}
.order-shipment-info span {
  display: block;
  margin-bottom: 5px;
  color: #555555;
  font-size: 14px;
}
.order-shipment-info strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}

.order-shipment-action {
  padding: 0 18px 17px;
}

.order-details-secondary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 39px;
  padding: 0 13px;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s;
}
.order-details-secondary-btn:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Customer
|--------------------------------------------------------------------------
*/
.order-customer-profile {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 17px 18px;
}
.order-customer-profile__avatar {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 14px;
  font-weight: 700;
}
.order-customer-profile strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.order-customer-profile span {
  display: block;
  color: #555555;
  font-size: 14px;
}

.order-customer-contact {
  padding: 0 18px 17px;
}
.order-customer-contact > div {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 11px;
  margin-top: 11px;
  border-top: 1px solid rgba(221, 221, 221, 0.6);
}
.order-customer-contact > div i {
  color: #177245;
  font-size: 17px;
}
.order-customer-contact > div span {
  overflow: hidden;
  color: #555555;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Address
|--------------------------------------------------------------------------
*/
.order-address {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 17px 18px;
}
.order-address strong {
