  gap: 8px;
}

.shipment-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 42px;
  padding: 0 14px;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #fff;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  transition: 0.2s;
}
.shipment-action-btn i {
  font-size: 17px;
}
.shipment-action-btn:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}
.shipment-action-btn--primary {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.shipment-action-btn--primary:hover {
  border-color: #177245;
  background: #177245;
  color: #fff;
  opacity: 0.92;
}

/*
|--------------------------------------------------------------------------
| Summary
|--------------------------------------------------------------------------
*/
.shipment-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 20px;
  border: 1px solid #ddd;
  border-radius: 11px;
  background: #fff;
}

.shipment-summary__item {
  padding: 17px 18px;
  border-right: 1px solid rgba(221, 221, 221, 0.7);
}
.shipment-summary__item:last-child {
  border-right: 0;
}
.shipment-summary__item span {
  display: block;
  margin-bottom: 5px;
  color: #555555;
  font-size: 14px;
}
.shipment-summary__item strong,
.shipment-summary__item a {
  display: block;
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.4;
  font-weight: 700;
  text-decoration: none;
}
.shipment-summary__item a {
  color: #177245;
}
.shipment-summary__item a:hover {
  text-decoration: underline;
}

.shipment-summary__success {
  color: #198754 !important;
}

/*
|--------------------------------------------------------------------------
| Main Grid
|--------------------------------------------------------------------------
*/
.shipment-details-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  align-items: start;
  gap: 20px;
}

.shipment-details-main,
.shipment-details-sidebar {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/*
|--------------------------------------------------------------------------
| Card
|--------------------------------------------------------------------------
*/
.shipment-details-card {
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 11px;
  background: #fff;
}
.shipment-details-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 16px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.shipment-details-card__header h2 {
  margin: 0;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 700;
}
.shipment-details-card__header > div > span {
  display: block;
  margin-top: 3px;
  color: #555555;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Shipment Information
|--------------------------------------------------------------------------
*/
.shipment-info-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.shipment-info-item {
  padding: 16px 18px;
  border-right: 1px solid rgba(221, 221, 221, 0.6);
  border-bottom: 1px solid rgba(221, 221, 221, 0.6);
}
.shipment-info-item:nth-child(even) {
  border-right: 0;
}
.shipment-info-item:nth-last-child(-n+2) {
  border-bottom: 0;
}
.shipment-info-item > span:first-child {
  display: block;
  margin-bottom: 5px;
  color: #555555;
  font-size: 14px;
}
.shipment-info-item > strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.shipment-info-item > a {
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}
.shipment-info-item > a:hover {
  text-decoration: underline;
}

/*
|--------------------------------------------------------------------------
| Status
|--------------------------------------------------------------------------
*/
.shipment-status {
  display: inline-flex !important;
  align-items: center;
  gap: 6px;
  width: fit-content;
  min-height: 27px;
  padding: 4px 9px;
  border-radius: 20px;
  font-size: 14px !important;
  line-height: 1.3;
  font-weight: 600 !important;
}
.shipment-status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.shipment-status--processing {
  background: rgba(13, 202, 240, 0.1);
  color: #087f99;
}
.shipment-status--pending {
  background: rgba(255, 193, 7, 0.12);
  color: #947000;
}

/*
|--------------------------------------------------------------------------
| Tracking
|--------------------------------------------------------------------------
*/
.shipment-tracking {
  padding: 20px 20px 20px 28px;
}

.shipment-tracking__item {
  position: relative;
  display: flex;
  gap: 13px;
  min-height: 82px;
}
.shipment-tracking__item:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 30px;
  left: 13px;
  width: 1px;
  height: calc(100% - 5px);
  background: #ddd;
}
.shipment-tracking__item--completed:not(:last-child)::before {
  background: #198754;
}
.shipment-tracking__item--active:not(:last-child)::before {
  background: #ddd;
}

.shipment-tracking__indicator {
  position: relative;
  z-index: 2;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #ddd;
  border-radius: 50%;
  background: #fff;
  color: #999;
  font-size: 14px;
}
.shipment-tracking__item--completed .shipment-tracking__indicator {
  border-color: #198754;
  background: #198754;
  color: #fff;
}
.shipment-tracking__item--active .shipment-tracking__indicator {
  border-color: #177245;
  background: #177245;
  color: #fff;
}

.shipment-tracking__content {
  padding-bottom: 20px;
}
.shipment-tracking__content strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.shipment-tracking__content span {
  display: block;
  margin-bottom: 4px;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.shipment-tracking__content small {
  display: block;
  color: #888;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Address
|--------------------------------------------------------------------------
*/
.shipment-address {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  padding: 18px;
}

.shipment-address__icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 19px;
}

.shipment-address__content {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.shipment-address__content strong {
  margin-bottom: 2px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.shipment-address__content span {
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*
|--------------------------------------------------------------------------
| Items Table
|--------------------------------------------------------------------------
*/
.shipment-items-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.shipment-items-table {
  width: 100%;
  min-width: 650px;
  border-collapse: collapse;
}
.shipment-items-table th,
.shipment-items-table td {
  padding: 14px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.65);
  text-align: left;
  vertical-align: middle;
  font-size: 14px;
}
.shipment-items-table th {
  background: #F2F4F7;
  color: #555555;
  font-weight: 600;
  white-space: nowrap;
}
.shipment-items-table td {
  color: #555555;
}
.shipment-items-table tbody tr:last-child td {
  border-bottom: 0;
}

/*
|--------------------------------------------------------------------------
| Product
|--------------------------------------------------------------------------
*/
.shipment-product {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 280px;
}
.shipment-product__image {
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #f7f7f7;
}
.shipment-product__image img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}
.shipment-product strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.shipment-product span {
  display: block;
  color: #555555;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Quantity
|--------------------------------------------------------------------------
*/
.shipment-quantity {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid #ddd;
  border-radius: 6px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

/*
|--------------------------------------------------------------------------
| Customer
|--------------------------------------------------------------------------
*/
.shipment-customer {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 17px 18px;
}
.shipment-customer__avatar {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 14px;
  font-weight: 700;
}
.shipment-customer strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.shipment-customer span {
  display: block;
  color: #555555;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Customer Contact
|--------------------------------------------------------------------------
*/
.shipment-customer-contact {
  padding: 0 18px 17px;
}
.shipment-customer-contact > div {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 11px;
  margin-top: 11px;
  border-top: 1px solid rgba(221, 221, 221, 0.6);
}
.shipment-customer-contact > div i {
  color: #177245;
  font-size: 17px;
}
.shipment-customer-contact > div span {
  overflow: hidden;
  color: #555555;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Carrier
|--------------------------------------------------------------------------
*/
.shipment-carrier-box {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 17px 18px;
}
.shipment-carrier-box__icon {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 19px;
}
.shipment-carrier-box strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.shipment-carrier-box span {
  display: block;
  color: #555555;
  font-size: 14px;
}

.shipment-carrier-details {
  padding: 0 18px 17px;
}
.shipment-carrier-details > div {
  padding-top: 11px;
  margin-top: 11px;
  border-top: 1px solid rgba(221, 221, 221, 0.6);
}
.shipment-carrier-details > div span {
  display: block;
  margin-bottom: 4px;
  color: #555555;
  font-size: 14px;
}
.shipment-carrier-details > div strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

/*
|--------------------------------------------------------------------------
| Quick Actions
|--------------------------------------------------------------------------
*/
.shipment-quick-actions {
  display: flex;
  flex-direction: column;
  padding: 7px 0;
}

.shipment-quick-action {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 11px 18px;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s;
}
.shipment-quick-action i {
  width: 20px;
  color: #177245;
  font-size: 17px;
  text-align: center;
}
.shipment-quick-action:hover {
  background: rgba(23, 114, 69, 0.04);
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Note
|--------------------------------------------------------------------------
*/
.shipment-note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 17px 18px;
}
.shipment-note i {
  margin-top: 2px;
  color: #177245;
  font-size: 17px;
}
.shipment-note p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*
|--------------------------------------------------------------------------
| Responsive XL
|--------------------------------------------------------------------------
*/
@media (min-width: 1200px) and (max-width: 1399px) {
  .shipment-details-grid {
    grid-template-columns: minmax(0, 1fr) 300px;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive LG
|--------------------------------------------------------------------------
*/
@media (min-width: 992px) and (max-width: 1199px) {
  .shipment-details-grid {
    grid-template-columns: 1fr;
  }
  .shipment-details-sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
/*
|--------------------------------------------------------------------------
| Responsive MD
|--------------------------------------------------------------------------
*/
@media (min-width: 768px) and (max-width: 991px) {
  .shipment-details-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .shipment-details-page__actions {
    width: 100%;
  }
  .shipment-action-btn {
    flex: 1;
  }
  .shipment-details-title {
    align-items: flex-start;
    flex-direction: column;
  }
  .shipment-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .shipment-summary__item {
    border-right: 0;
    border-bottom: 1px solid rgba(221, 221, 221, 0.7);
  }
  .shipment-summary__item:nth-child(odd) {
    border-right: 1px solid rgba(221, 221, 221, 0.7);
  }
  .shipment-summary__item:nth-last-child(-n+2) {
    border-bottom: 0;
  }
  .shipment-details-sidebar {
    grid-template-columns: 1fr;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive XS
|--------------------------------------------------------------------------
*/
@media (max-width: 767px) {
  .shipment-details-title h1 {
    font-size: 24px;
  }
  .shipment-summary {
    grid-template-columns: 1fr;
  }
  .shipment-summary__item {
    border-right: 0 !important;
    border-bottom: 1px solid rgba(221, 221, 221, 0.7);
  }
  .shipment-summary__item:last-child {
    border-bottom: 0;
  }
  .shipment-details-page__actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .shipment-action-btn {
    width: 100%;
    padding: 0 9px;
  }
  .shipment-details-card__header {
    padding: 14px;
  }
  .shipment-info-grid {
    grid-template-columns: 1fr;
  }
  .shipment-info-item {
    border-right: 0 !important;
  }
  .shipment-info-item:last-child {
    border-bottom: 0;
  }
  .shipment-tracking {
    padding: 18px 14px 18px 18px;
  }
  .shipment-address {
    padding: 14px;
  }
  .shipment-customer {
    padding: 14px;
  }
  .shipment-customer-contact {
    padding: 0 14px 14px;
  }
  .shipment-carrier-box {
    padding: 14px;
  }
  .shipment-carrier-details {
    padding: 0 14px 14px;
  }
  .shipment-note {
    padding: 14px;
  }
}

